WordHunterWoW_QuestEN[8873] = { title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", objectives = "Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar.  You can also talk to Lunar Festival Harbingers in other capital cities.", completion = "Welcome, {name}.  Are you here to join in the festivities?" }
WordHunterWoW_QuestEN[8874] = { title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", objectives = "Talk to the Lunar Festival Harbinger in the entrance to the Undercity.  You can also talk to Lunar Festival Harbingers in other capital cities.", completion = "Welcome, {name}.  Are you here to join in the festivities?" }
WordHunterWoW_QuestEN[8875] = { title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", objectives = "Talk to the Lunar Festival Harbinger at the Elder Rise in Thunder Bluff.  You can also talk to Lunar Festival Harbingers in other capital cities.", completion = "Welcome, {name}.  Are you here to join in the festivities?" }
WordHunterWoW_QuestEN[8876] = { title = "Small Rockets", description = "", objectives = "I hold the secrets to creating Lunar Festival rockets, and I am happy to share my knowledge with the honored.\n\nIn exchange for coins of ancestry, I can offer you the recipe to make a small rocket...", progress = "I hold the secrets to creating Lunar Festival rockets, and I am happy to share my knowledge with the honored.\n\nIn exchange for coins of ancestry, I can offer you the recipe to make a small rocket...", completion = "Ah, very well.  Here are your recipes, {name}, and my Elune bless you." }
WordHunterWoW_QuestEN[8877] = { title = "Firework Launcher", description = "", objectives = "Although rockets are a wonderful way to celebrate, in order to see their glory... they must be fired from a launcher.\n\nBring me coins of ancestry and I can offer you the knowledge to create rocket launchers like the ones you see in Moonglade.", progress = "Although rockets are a wonderful way to celebrate, in order to see their glory... they must be fired from a launcher.\n\nBring me coins of ancestry and I can offer you the knowledge to create rocket launchers like the ones you see in Moonglade.", completion = "Here you are, {name}.  Here is the schematic to create a firework launcher.  Place launchers where you wish to celebrate, and then welcome your friends to join you!" }
WordHunterWoW_QuestEN[8878] = { title = "Festive Recipes", description = "", objectives = "The dresses and pant suits you see are traditional clothes from many years past.  They are worn in honor of old ways and loved ones gone.\n\nIf you bring me coins of ancestry, {name}, then I will give you the pattern to create traditional red dresses or suits.", progress = "The dresses and pant suits you see are traditional clothes from many years past.  They are worn in honor of old ways and loved ones gone.\n\nIf you bring me coins of ancestry, {name}, then I will give you the pattern to create traditional red dresses or suits.", completion = "Here are the patterns, {name}.  I am sure you will find the product of this knowledge quite beautiful." }
WordHunterWoW_QuestEN[8879] = { title = "Large Rockets", description = "", objectives = "Large Festival rockets light up the sky brilliantly - only the cluster rockets rival their magnificence!\n\nBring me coins of ancestry, {name}, and I shall share the knowledge of their creation.", progress = "Large Festival rockets light up the sky brilliantly - only the cluster rockets rival their magnificence!\n\nBring me coins of ancestry, {name}, and I shall share the knowledge of their creation.", completion = "Very well - I accept these coins of ancestry.  Here are your recipes, {name}.  May you use them to spread Elune's glory!" }
WordHunterWoW_QuestEN[8880] = { title = "Cluster Rockets", description = "", objectives = "Cluster rockets are a collection of individual rockets, and their beauty is awesome!  Bring me coins of ancestry and I will share the knowledge of their creation to you...", progress = "Cluster rockets are a collection of individual rockets, and their beauty is awesome!  Bring me coins of ancestry and I will share the knowledge of their creation to you...", completion = "Here you are, {name}.  Take these recipes and learn their secrets.  I bid you fortune, and I look forward to seeing your magnificent creations." }
WordHunterWoW_QuestEN[8881] = { title = "Large Cluster Rockets", description = "", objectives = "Large cluster rockets require vast resources and skill to create, but their brilliance and beauty is worth that effort!  Bring me coins of ancestry and I will grant you the knowledge of their crafting.", progress = "Large cluster rockets require vast resources and skill to create, but their brilliance and beauty is worth that effort!  Bring me coins of ancestry and I will grant you the knowledge of their crafting.", completion = "Thank you, {name}.  Here is the recipe for large cluster rockets.  May your products bring joy and luck to all those who gaze up them." }
WordHunterWoW_QuestEN[8882] = { title = "Cluster Launcher", description = "", objectives = "The most splendid fireworks shows must include cluster rockets, and those cluster rockets must be fired from cluster launchers!  Is it not then logical for you to learn the secrets of making cluster launchers?  Bring me coins of ancestry and I will give this knowledge to you.", progress = "The most splendid fireworks shows must include cluster rockets, and those cluster rockets must be fired from cluster launchers!  Is it not then logical for you to learn the secrets of making cluster launchers?  Bring me coins of ancestry and I will give this knowledge to you.", completion = "Here is your schematic.  Study it closely, and learn...\n\nGood luck, {name}.  May your celebrations rival that of the Lunar Festival itself!" }
WordHunterWoW_QuestEN[8883] = { title = "Valadar Starsong", description = "Now that you have your Lunar Festival invitation, you may travel to Moonglade!  There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration.\n\nTravel to Moonglade through the greater moonlight and speak with Valadar Starsong; see what prizes you might gain during the festival!", objectives = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.", completion = "{name}, welcome to Nighthaven, host of the Lunar Festival!  Although our village is normally remote and sequestered from the peoples of Azeroth, during this time of celebration we open our arms and hearts to all.\n\nEnjoy your visit, {name}, and speak with me or my sister again when ready." }
WordHunterWoW_QuestEN[8893] = { title = "The Super Egg-O-Matic", description = "", objectives = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", progress = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", completion = "You place the hippogryph egg into the machine. A series of beeps follows along with some strange mechanical sounds.\n\nIt appears that the Eggometer has weighed, measured, and packaged your egg. Now that's speedy service!" }
WordHunterWoW_QuestEN[8897] = { title = "Dearest Colara,", description = "I've got to keep watch here at the gate, but I'm always worrying about my sweetheart, Colara. I only get to see her for a few hours, if I'm lucky, and well, just look at me. I've got a minor officer's pay and I could be called to the front any day now.\n\nWould she just forget about me? There are a lot of men in the city. A lot of rich ones.\n\nAnyways, I've scribbled some things down... nothing much, but if you could take it to her for me, that'd be great.", objectives = "Deliver Lieutenant Heldric's Carefully Penned Note to Colara Dean outside the bank in Stormwind.", progress = "Hello there, handsome. Something I can help you with?", completion = "Oh, isn't that sweet! This is the first time he's ever sent me something. Do you suppose he's getting serious?\n\nColara Heldric? I suppose it has a ring to it. Oh, but I'm getting ahead of myself. Thank you." }
WordHunterWoW_QuestEN[8898] = { title = "Dearest Colara,", description = "I met a lass in Stormwind when I was last there on the bank's business. She stole my heart away. Now, I can't stop thinking about her! I'd like to send her this message - I've rewritten it twelve times!\n\nThe mail is so full now, and I want to make sure it gets there.\n\nIf you're heading that way, could you help me?", objectives = "Deliver the Creased Letter to Colara Dean outside the bank in Stormwind.", progress = "Hello there, handsome. Something I can help you with?", completion = "Tormek? Oh yes, I do remember him. He had quite a nice beard and smile underneath.\n\nAh, I can't believe he remembered me!" }
WordHunterWoW_QuestEN[8899] = { title = "Dearest Colara,", description = "How to describe her beauty? Thousands of years of words and I am at a loss.\n\nThese mortals confound the mind and leave us babbling fools.\n\nI've stared at these words too long. No more eloquent meaning can I squeeze from them. No, she must have it now, or some other suitor will surely steal her eye.", objectives = "Deliver the Immaculate Letter to Colara Dean outside the bank in Stormwind.", progress = "Hello there, handsome. Something I can help you with?", completion = "I've never received something like this before. How lovely!" }
WordHunterWoW_QuestEN[8900] = { title = "Dearest Elenia,", description = "She was so sad. I could see that, once I saw past her state. I mean, she seemed sad - wouldn't you?\n\nBut after talking to her, there was a connection. I didn't think anyone could understand what I was thinking, but she could.\n\nWhen I told the others, they laughed at me, so I never spoke with her again. But I miss her. Can you take this letter to her for me? I want to be sure it finds her hands.", objectives = "Deliver the Slightly Creased Note to Elenia Haydon near the bank in the Undercity.", progress = "Oh, and to what do I owe this pleasure?", completion = "You wouldn't expect an orc to be so eloquent. Of course, we never really had a chance to know them before now. Thank you for bringing this to me." }
WordHunterWoW_QuestEN[8901] = { title = "Dearest Elenia,", description = "Have you ever known love, young one? It was a thing foreign to me until lately, when I met a girl from the Undercity, Elenia. It is rare enough for one of my kind to look outside our own, let alone one of the Forsaken.\n\nBut now thoughts of her occupy my mind both days and nights.\n\nIf you can, could you take this letter to her? I want her to come here to Mulgore. I hope that she will say yes.", objectives = "Deliver the Carefully Written Letter to Elenia Haydon near the bank in the Undercity.", progress = "Oh, and to what do I owe this pleasure?", completion = "What kind words Temma writes for me. But, as much as his words move me, I cannot consider the love of a tauren. In thoughts, body and mind we are too different.\n\nIt is good I do not have to receive these thoughts of his in person. I could not bear to break his heart." }
WordHunterWoW_QuestEN[8902] = { title = "Dearest Elenia,", description = "A lifetime ago, I was betrothed to marry Elenia, my childhood sweetheart. It's been years since I thought about her last, but of late, she frequently occupies my thoughts.\n\nPerhaps, even with everything that has passed, there can be some room in each other's lives for our love.\n\nI'm sure she has changed, also. Can you deliver this letter to her for me? I am too nervous to give it in person.", objectives = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity.", progress = "Oh, and to what do I owe this pleasure?", completion = "This brings back memories from a lifetime ago, {name}. Elenia Tor. That was going to be my name, you know. We would have a beautiful ceremony out on the shores of the lake. When he retired, we'd find a farm to retire to.\n\nSimple dreams, then.\n\nBut if he saw me now, I doubt he'd even see Elenia in me. Only cold flesh and a dead heart..." }
WordHunterWoW_QuestEN[8903] = { title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's not proper, it's an eyesore, and at worst, it could be a threat to the the safety of the Alliance itself.\n\nJust think: what if the guards have been taken in by this strange affliction? Something must be done.\n\nGo to one of the guards here in Stormwind and see if they've been caught up in this foolishness.", objectives = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind.", progress = "Was I right to worry? Are the guards afflicted with this lovesickness?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this." }
WordHunterWoW_QuestEN[8904] = { title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", objectives = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.", progress = "Was I right to worry? Have our idiot guardians been overcome?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this." }
WordHunterWoW_QuestEN[8905] = { title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge.", progress = "Have you brought me what I requested of you, {name}?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces." }
