WordHunterWoW_QuestEN[9007] = { title = "Saving the Best for Last", description = "A truly amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.\n\nAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.", objectives = "Give Mokvar your Wildheart Cowl and Wildheart Vest.", progress = "Are you ready to give me your Wildheart pieces in exchange for your new Feralheart Cowl and Vest?", completion = "I will truly miss you, {name}. There is a debt that I owe you, which I may never be able to repay.\n\nEnjoy your new head and chest armor. May it protect you for a long time to come, and help you to achieve even greater honor!" }
WordHunterWoW_QuestEN[9008] = { title = "Saving the Best for Last", description = "A truly amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.\n\nAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.", objectives = "Give Mokvar your Beaststalker's Cap and Beaststalker's Tunic.", progress = "Are you ready to give me your Beaststalker's pieces in exchange for your new Beastmaster's Cap and Tunic?", completion = "I will truly miss you, {name}. There is a debt that I owe you, which I may never be able to repay.\n\nEnjoy your new head and chest armor. May it protect you for a long time to come, and help you to achieve even greater honor!" }
