WordHunterWoW_QuestEN[78150] = { title = "Friend of the Library", description = "", objectives = "Thanks to your donations, the library is thriving.\n\nPlease, take this.", completion = "Thanks to your donations, the library is thriving.\n\nPlease, take this." }
WordHunterWoW_QuestEN[78261] = { title = "The Horn of Xelthos", description = "<A note sits in the chest>\n\nHello, {name}.\n\nI desire a treasure known as The Horn of Xelthos, which is somewhere within Shadowfang Keep.\n\nVenturing inside the keep usually calls for backup. However, for this job, a low profile is of utmost importance.\n\nYou must go alone.\n\nI have a contact, by the name of Veenix, in the Stonetalon Mountains. He should be able to help you get past the courtyard gate. The rest is up to you. \n\nReturn the horn here, and your payment will be sent soon after.\n\n- C", objectives = "Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone.", progress = "<The chest sits, empty.>", completion = "<You place The Horn of Xelthos into the chest>" }
WordHunterWoW_QuestEN[78270] = { title = "Goblin Lockpicks", description = "<A note sits in the chest>\n\nHello again, {name}.\n\nI desire a treasure known as The Horn of Xelthos, which is somewhere within Shadowfang Keep.\n\nVenturing inside the keep usually calls for backup. However, for this job, a low profile is of utmost importance.\n\nYou must go alone.\n\nI have a contact, by the name of Veenix, in the Stonetalon Mountains. He should be able to help you get past the courtyard gate. The rest is up to you. \n\nReturn the horn here, and your payment will be sent soon after.\n\n- C", objectives = "Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village.", progress = "You said you're breaking into Shadowfang...alone? You've got some guts! \n\nI can hook you up with explosives to get past the gate, but I'll need a work order to make it look legit on the books. An employee around here's likely carrying one. Probably someone who does a lot of tinkering or building.", completion = "Nice job, {name}. I figure that was a cakewalk for someone in your line of work.\n\nAs promised, here's the goods." }
WordHunterWoW_QuestEN[78307] = { title = "The Horn of Xelthos", description = "Description", objectives = "Log", completion = "<A note sits in the chest>\n\nFor {name}. I'll be seeing you.\n\n- C" }
WordHunterWoW_QuestEN[78676] = { title = "The Eye of Bhossca", description = "<A note sits in the chest>\n\nGlad to have you back, {name}.\n\nThe latest object of my desire is an artifact known as the Eye of Bhossca. My sources tell me the eye is somewhere within the Scarlet Monastery. As with Shadowfang Keep, you must infiltrate the monastery alone.\n\nIt may behoove you to find a disguise before going in. It will make getting around a touch easier. I'm sure you could find something on the monastery's grounds.\n\nReturn the eye here, and payment will be delivered as before.\n\n- C", objectives = "Find The Eye of Bhossca inside of the Scarlet Monastery. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone.", progress = "<The chest sits, empty.>", completion = "<You place The Eye of Bhossca into the chest>" }
WordHunterWoW_QuestEN[78699] = { title = "The Eye of Bhossca", description = "Description", objectives = "Log", completion = "<A note sits in the chest>\n\nFor {name}. I'll be keeping an \"eye\" out for you.\n\n- C" }
WordHunterWoW_QuestEN[78823] = { title = "Terror of the Desert Skies", description = "The drawing is composed of rough, broad, strokes and seems to depict a large bird of prey. Despite the simple composition, the artist clearly viewed this creature with fear and awe. An expert on big game could likely tell you more.", objectives = "Bring the Primitive Drawing to Hemet Nesingwary in Stranglethorn Vale.", progress = "Got something for me, {class}?", completion = "Well now. This is certainly interesting..." }
WordHunterWoW_QuestEN[78830] = { title = "Terror of the Desert Skies", description = "This drawing reminds me of a story I'd heard on another expedition, not long ago. I was told of a great bird, Gharrik, who reigns over the Badlands as an apex predator.\n\nShe was last spotted northeast of Camp Cagg. Perhaps her nest is somewhere nearby?\n\nYou'll need live bait to draw her out. I'll lend you a cage to catch some. Small wildlife is scarce in the Badlands, so you'll need to find your bait elsewhere.\n\nA quill from Gharrik would make a fine prize. You'd certainly be the talk of the camp.", objectives = "Get a Crimson Trophy Quill from Gharrik in the Badlands. Then, return to Hemet Nesingwary in Stranglethorn Vale.", progress = "How goes the hunt? Surely the bird hasn't got you beat!", completion = "Now there's a feather for your cap! Nicely done, {name}.\n\nYou can rest here for a while, if you like. I'm sure your trek through the desert was arduous." }
WordHunterWoW_QuestEN[78916] = { title = "The Heart of the Void", description = "The dread beast Aku'mai lies dead.  Hidden amongst the viscera and gore of its swollen corpse is an enormous iridescent pearl teeming with raw Void energy.", objectives = "Bring the Blackfathom Pearl to Dawnwatcher Selgorm in Darnassus.", progress = "{name}, what news do you have from Blackfathom?", completion = "The servant of the Old Gods, Aku'mai, is dead. Such an accomplishment is the stuff of real heroes. \n\nThis object may be the key to much greater understanding of the nature of the Void and its effect on our world, It must be studied at once. Thank you, {name}." }
WordHunterWoW_QuestEN[78917] = { title = "The Heart of the Void", description = "The dread beast Aku'mai lies dead.  Hidden amongst the viscera and gore of its swollen corpse is an enormous iridescent pearl teeming with raw Void energy.", objectives = "Bring the Blackfathom Pearl to Bashana Runetotem in Thunder Bluff.", progress = "{name}, what news do you have from Blackfathom?", completion = "The servant of the Old Gods, Aku'mai, is dead. You have done a mighty service for the denizens of Kalimdor with this deed.\n\nThe pearl may also be the key to much greater understanding of the nature of the Void and its effect on our world.  It must be studied at once. Walk with the Earth Mother, {name}." }
WordHunterWoW_QuestEN[79007] = { title = "... and that note you found", description = "<The faint radiance of the embers darkening, you stumble across the remnants of a recent fire.\n\nAmidst the scattered provisions, you discover a blistered note.>\n\n\"Not all that burns is lost. Find the twin land, find the place.\"", objectives = "Charred remains of the note serve as your only guide.", completion = "As you stumble upon the remnants of yet another charred corpse, your gaze falls upon a message secured to a wooden plank." }
WordHunterWoW_QuestEN[79008] = { title = "... and that note you found", description = "<The faint radiance of the embers darkening, you stumble across the remnants of a recent fire.\n\nAmidst the scattered provisions, you discover a blistered note.>\n\n\"Not all that burns is lost. Find the twin land, find the place.\"", objectives = "Charred remains of the note serve as your only guide.", completion = "As you stumble upon the remnants of yet another charred corpse, your gaze falls upon a message secured to a wooden plank." }
WordHunterWoW_QuestEN[79090] = { title = "Repelling Invaders", description = "Some of the Warsong Outriders lie defeated, but the battle still rages...", objectives = "Bring the Warsong Outrider Mark to Felore Moonray, Priestess of the Moon, at the Moonwell base in Ashenvale.", progress = "{name}, what news do you have from the front?", completion = "These Horde invaders still sully our lands and harvest from our sacred wilderness. Continue to drive them out!\n\nThis sacred battle hymn may inspire you to fight them with greater determination. Thank you, {name}." }
WordHunterWoW_QuestEN[79091] = { title = "Archmage Antonidas: The Unabridged Autobiography", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. You say this is from the Ironforge library? ...I'm sure they won't miss it.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
