WordHunterWoW_QuestEN[79098] = { title = "Clear the Forest!", description = "This one is slain, but these infuriating alliance continue to fight... what is this charm?", objectives = "Bring the Silverwing Sentinel Charm to Kazragore, Far Seer, at the Bonfire base in Ashenvale.", progress = "{name}, what news do you have from the front?", completion = "These Alliance dogs still prevent us from harvesting the resources needed for Orgrimmar. Continue to drive them out!\n\nThis Warsong battle drum will inspire you to fight them with greater determination. Lok'tar Ogar, {name}!" }
WordHunterWoW_QuestEN[79192] = { title = "Stepping Stones", description = "The note begins, \"Mission said they were both making deliveries for New Plague. Looks like simple apothecary accidents to me. Find my cozy spot in the mountains between The Barrens and Desolace if you want a safe place to talk.\"", objectives = "You tear the note from the plank and read the scrawled writing.", completion = "Backcountry adventurers and mercenaries alike undoubtedly make camp here. The corner of a note flapping in the breeze catches your eye and you reach for it." }
WordHunterWoW_QuestEN[79229] = { title = "Highway Robbery", description = "The campsite before you is a grisly scene. Judging by the remains, the victims were two humans and a dwarf. Markings on the bones indicate a savage attack, but the looted supplies tell you this wasn't done by an animal. The wounds don't match centaur weaponry either.\n\nPerhaps an experienced scavenger of these lands would know what to make of this.", objectives = "Find someone in Desolace who knows about the pillaged campsite.", completion = "Ah, so you found another one..." }
WordHunterWoW_QuestEN[79235] = { title = "On the Lam", description = "I've found a couple of scenes like you describe, {name}. Always camps of humans and dwarves. Rumor among the caravans is a group of Horde marauders did it. Seems likely given the victims, and how brutal the attacks were.\n\nApparently the bandits fled Desolace once an Alliance marshal got hot on their trail.\n\nIf you're looking to track one of 'em down, I'd check Booty Bay. Ports always have shady characters coming and going. You might catch one trying to get a boat to somewhere.", objectives = "Find one of the Desolace marauders.", completion = "You need something? Make it quick." }
WordHunterWoW_QuestEN[79236] = { title = "Cherry for Your Thoughts?", description = "You with the marshal? No, you don't look like it.\n\nThe rumors you've heard are only half true. Yes, we were pillaging human and dwarven camps, but we weren't doing it for the Horde. We were privately employed.\n\nI'll tell you the whole story if you buy me some grog.", objectives = "Bring a Cherry Grog to Tokal, in Booty Bay, to hear the rest of her story.", progress = "How's that drink coming?", completion = "Ah, that's the stuff. Now, where was I?" }
WordHunterWoW_QuestEN[79242] = { title = "No Honor Among Thieves", description = "As I was saying...\n\nOur boss wasn't with the Horde. She was a night elf named Illari Duskfeather. She gave us intel on the camps, and even let us keep most of the loot. She only kept a few of the rarer finds.\n\nOnce the marshal was on our tail, though, she left us for dead. I don't know her motives, but I think we were set up as patsies.\n\nI'm not the vengeful type, but I won't stop someone else from hunting her down. If you're looking for her, she once mentioned a hideout on the coast of Arathi.", objectives = "Find Illari Duskfeather on the coast of Arathi Highlands, and get access to her cache of stolen loot.", progress = "<Using Illari's key, you unlock the cache.>", completion = "<Inside of the cache, you find a small box, along with some coin.>" }
WordHunterWoW_QuestEN[79358] = { title = "Storm, Earth, and Fire", description = "Floodin' the Thousand Needles is no small feat, {name}. If I hadn't felt the elements' outrage meself, I'd have never believed it. But here we are.\n\nThe quilboar aren't the first tae weaponize the elements irresponsibly, and they won't be the last. If we want to prepare our own counter-ritual, we'll need a better understanding of these twisted elements. Take this book. It details the many denizens of Azeroth and how they practice shamanism.\n\nIf you can learn from them, maybe we can find a solution.", objectives = "Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Veyric Thunderhame in Arathi Highlands.", completion = "<Hmmph... the large tauren snorts as he reads the parchment.>\n\nOne things certain... whoever this note is from is right about their preparations going unseen. We've been too busy dealing with the centaur and harpies to send out wind riders to patrol the canyon and bluffs.\n\nYou have our gratitude for alerting us to this threat, but we might still need further assistance." }
WordHunterWoW_QuestEN[79360] = { title = "Elemental Aid", description = "Now that you have mastered the elements, you have an obligation to them, and thus to all of Azeroth herself. We call to them for aid, we do not demand their power. It is time you return the favors granted to you. And I think I know how.\n\nThe quilboar twist the elements for their own ends, and seem to be extending their reach within these borders. Go into their kraul and put an end to whatever they scheme. These lands must be protected.", objectives = "Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans.", progress = "Danger? There's been no reports of anything like that. And our wind riders are far too busy to spend their time chasing ghost stories.", completion = "Hmmph... One thing's certain. Whoever this note is from is right about their preparations going unseen. We've been too busy dealing with the centaur and harpies to send out wind riders to patrol the canyons.\n\nYou have our gratitude for alerting us to this threat, but we might still need further assistance." }
WordHunterWoW_QuestEN[79361] = { title = "Storm, Earth, and Fire", description = "So the quilboar mean to flood the Thousand Needles with their twisted shamanism, do they? It seems almost unimaginable, but you yourself have seen that these creatures are not to be taken lightly.\n\nI had wished to continue your training in earnest, but there is no time for that now. These lands are home to many different creatures, friend and foe alike, and none of them deserve such a fate. We must act.\n\nTake this tome. It was meant for study, but may now hold the key to dispersing this coming storm.", objectives = "Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Prate Cloudseer in Thousand Needles.", progress = "There are many who practice shamanism in this world. It is up to us to ensure that the land is protected from misuse.", completion = "I can feel their corruption from here. The twisted elementals the quilboar are summoning should be drawn to the cleansing ritual." }
WordHunterWoW_QuestEN[79362] = { title = "Grant's Shield", description = "A shield left behind by the specter of Grant Valor, father of the Valor family and hero of Raven Hill.\n\nWith Grant's spirit still battling the undead, perhaps his unfinished business was to slay the scourge that injured him in the Raven Hill Cemetery. It is likely the one his mace is still imbedded in.", objectives = "Find Grant's Mace on one of the skeletons in Raven Hill Cemetery then return to Sirra Von'Indie in Darkshire for more information.", progress = "You' legs be lookin' a wobbly der. De ground be shakin?", completion = "Let's get ready to rumble, ya?" }
WordHunterWoW_QuestEN[79363] = { title = "Silvia's Sword", description = "A sword left by the spirit of Raven Hill's guard, Silvia Valor, who lived her life protecting civilians and their homes.\n\nWith Silvia's spirit still visiting farmsteads, perhaps her unfinished business was to route the defias who have taken up residence in Addle's Stead south of Raven Hill.", objectives = "Defeat 7 Defias Night Blades and 7 Defias Enchanters in Addle's Stead then return to Sirra Von'Indi in Darkshire for more information.", progress = "Wade into any danger yet?", completion = "Shake dat sludge off, we almost done." }
WordHunterWoW_QuestEN[79364] = { title = "Eyes on the Sky", description = "The note you found says the Razormane have burrowed into the Thousand Needles for some sort of unseen ritual. Raging storms and rising tides...\n\nThe quilboar must be using some cruel sorcery they learned from Hirzek, a shaman who went to great lengths to twist the elements. If they plan to flood the canyon, this would require devastating elemental powers.\n\nWe are ill equipped to deal with this, but a powerful shaman like you must have an idea. Return to your allies and see if you can't find an answer.", objectives = "Speak with Prate Cloudseer in Thousand Needles.", progress = "We need a larger vial and one of crystal clarity to contain these elements.", completion = "You have returned. Do you see the skies darkening? What news have you about the quilboar threat?" }
WordHunterWoW_QuestEN[79365] = { title = "With Wind Beneath Your Wings", description = "Here mon, a Squall-breakers Potion be what you need. Drink this to protect yourself against the elements of the storm, but remember it only goin' to last for a short while.\n\nNow go, return to your friends in need. There's nothing more I can do for you.", objectives = "Return to Rau Cliffrunner in Thousand Needles at Freewind Post.", completion = "Our wind riders have found something, but they have been unable to get close enough to assess the situation. Were you able to find anything that might help us?" }
WordHunterWoW_QuestEN[79366] = { title = "Heed My Call", description = "Now that you have the twisted totems, we must wield them to summon forth the corrupted elementals the quilboar are calling upon. Defeat them to cleanse these lands and put an end to the Razormane's abominable ritual then report back to Rau Cliffrunner with your success.\n\nYou should begin your clensing at the steam pools to the west. That area is rich with each of the elements. But be careful, {name}. The quilboar will not sit idly while you interrupt their plans.", objectives = "Use the Twisted Totems to put an end to the quilboar ritual.", progress = "Have you any news of the storm?", completion = "The rumbling ground fell silent and in my heart I knew you had saved us. You have our gratitude, {name}. You do your Earthen Ring proud." }
WordHunterWoW_QuestEN[79442] = { title = "The Tempest's Weapons", description = "Our people cannot thank you enough, but I have no real use for this eye. I have heard of an old shaman in the Alterac mountains that has an eye for storm elemental magic. Perhaps he may be able to craft something for you.", objectives = "Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains.", progress = "Great battle with de elements, mm? Tings turned out how they was always meant to.\n\nBut since you here, what brings you to ol' Bath'rah?", completion = "Ah, this be a powerful artifact, friend! I haven't crafted with some'ting like this in a long time.\n\nYou take good care o' dis now, ya here? Looks like ya went through plenty to get it!" }
WordHunterWoW_QuestEN[79482] = { title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", objectives = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Ironforge b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold..." }
WordHunterWoW_QuestEN[79483] = { title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", objectives = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains." }
WordHunterWoW_QuestEN[79492] = { title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Greatfather Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!", objectives = "Find Metzen the Reindeer.  Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Wulmort Jinglepocket in Ironforge once Metzen is freed.", progress = "{name}!  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Greatfather Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!" }
WordHunterWoW_QuestEN[79495] = { title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!", objectives = "Find Metzen the Reindeer.  Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Kaymard Copperpinch in Orgrimmar once Metzen is freed.", progress = "{name}!  Did you find him?  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Great-father Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!" }
WordHunterWoW_QuestEN[79535] = { title = "Basilisks: Should Petrification be Feared?", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[79536] = { title = "Greater Friend of the Library", description = "", objectives = "Thanks to your donations, the library is thriving.\n\nPlease, take this." }
WordHunterWoW_QuestEN[79624] = { title = "Anyone Can Cook", description = "The recipe appears to be for some sort of meat dish. It is written in a language you don't understand. Ogre is your best guess, given the source and subject matter.\n\nOgres aren't usually culinary types but, if you knew one with such an inclination, they could translate the recipe for you.", objectives = "Find an ogre who can read the Illegible Recipe.", completion = "You have recipe? Skonk listening." }
WordHunterWoW_QuestEN[79637] = { title = "A Ticking Present", description = "", objectives = "Have a joyous Feast of Great-Winter from your friends at Smokeywood Pastures." }
WordHunterWoW_QuestEN[79677] = { title = "A Quick Grocery Run", description = "Other ogres laugh at Skonk because Skonk smaller than them. They say small ogre weak, so Skonk learn to cook instead of fight. This only cause more teasing, so Skonk run away to follow dream.\n\nSkonk can make dish, but need ingredients. You take note. Find ingredients. Skonk more focused on craft; not really logistics guy.", objectives = "Gather the ingredients for Skonk's dish, then bring them to him in Arathi Highlands" }
WordHunterWoW_QuestEN[79678] = { title = "Taste Testing", description = "Ok {race} buddy, it time for Skonk favorite part. Skonk have fire hot and ready, and want to share new dish with new friend. You do such big favors for Skonk; it only right you get some too!\n\nLet Skonk know when you ready for tasting.", objectives = "Taste test the recipe with Skonk." }
WordHunterWoW_QuestEN[79731] = { title = "The Troll Scroll", description = "<The ancient glyphs resolve into words before your eyes.>\n\nWhen Zul'Kunda's fountain runs with the waters of the holy spring, the gods grant their blessing.", objectives = "Solve the riddle of the scroll. Once you've done that, Hemet Nesingwary might like to hear the tale.", completion = "A magic fountain hidden in the jungle? What a story, {name}!\n\nThat gives me an idea for another chapter in my book! Let's see, where did I put that manuscript..." }
WordHunterWoW_QuestEN[79939] = { title = "The Broken Hammer", description = "<An ornate broken warhammer lies surrounded by dead Burning Blade Cultists and Scarlet Crusade warriors. A fight clearly happened here, and fairly recently. You also recognize this as the weapon of a paladin of the Order of the Silver Hand. \n\nWhile you've seen many hammers like this one, the quality and worksmanship of this weapon is fairly unique. You should search the area for clues, and return to Katherine with the broken hammer.>", objectives = "Recover clues about the recent battle at Mannoroc Coven, and return the Broken Warhammer to Katherine the Pure in Stormwind." }
WordHunterWoW_QuestEN[79940] = { title = "A Lost Brother", description = "<Katherine winces as she holds the shattered fragments of the broken hammer> \n\nI won't speak of this weapon's master in detail for the telling would fill me with shame, but I'll tell you what I can.", objectives = "Speak with Katherine the Pure and learn more about the broken hammer." }
WordHunterWoW_QuestEN[79945] = { title = "Orders from the Grand Crusader", description = "This appears to be orders from the Grand Crusader of the Scarlet Crusade himself, Dathrohan. It seems that Aeonas has run afoul of the Crusade. Judging by the scene before you, it appears that the Crusade was able to follow Aeonas here and apprehend him. It appears that he did not go down without a fight.\n\nThe charges levied against Aeonas are grave, but that would explain some of the scene you came upon in Desolace.", objectives = "Bring the Orders from the Grand Crusader back to Katherine the Pure." }
WordHunterWoW_QuestEN[79946] = { title = "A Brother In Need", description = "Due to the... unfortunate nature of why he left the order, it would be bad comedy for Aeonas to die at the hands of the Scarlet Crusade now. The Crusade is an organization of zealots and lunatics and they've been growing increasingly brazen in their willingness to commit violence against anyone who they imagine to be enemies of the light. Go to the Scarlet Monastery in Tirisfal Glades and find out if Aeonas still lives.", objectives = "Speak with Katherine to learn more about Aeonas, and then find him in the Scarlet Monastery." }
WordHunterWoW_QuestEN[79947] = { title = "Geomancy: The Stone-Cold Truth", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[79948] = { title = "Defensive Magics 101", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[79949] = { title = "A Web of Lies: Debunking Myths and Legends", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[79950] = { title = "Demons and You", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[79951] = { title = "Mummies: A Guide to the Unsavory Undead", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[79952] = { title = "RwlRwlRwlRwl!", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[79963] = { title = "By The Light's Grace", description = "<Aeonas needs immediate healing or he will die. Call upon the light and save him.>", objectives = "Heal Aeonas." }
WordHunterWoW_QuestEN[79970] = { title = "Aeonas the Vindicated", description = "Thank you for saving me, {class}. It seems that I'm not as young as I once was, and I think I'm going to need allies for what is to come. Please, meet me in Stormwind in the Cathedral of Light as soon as you are able.\n\nDon't worry about me, I can find my way out of here on my own. I just need a few moments to recover my strength", objectives = "Meet Aeonas at the Cathedral of Light in Stormwind." }
WordHunterWoW_QuestEN[79974] = { title = "Wet Job", description = "\"Always like to keep a reserve stash nearby in the off chance I've got to flee in a hurry.\n\nThe face of this mountainside is so beautiful you might say it was carved from the waterfalls of time. \nThat's the eagles nest, that's what you're looking for.\"", objectives = "Dusting off a messenger bag emerging from the soil, you find a parchment nestled among the supplies.", completion = "Dwarven Engineering, always a marvel." }
WordHunterWoW_QuestEN[79975] = { title = "Eagle's Fist", description = "<You find a carefully folded letter inside of the toolbox.>\n\n\"From here, with the right tools, you call the shots. Great place to launch a parachute glider.\n\nMy loyalty to the Eagle and Fist requires distance in order to serve them best. This barricade has had better days, like the Old Kingdoms it once defended, but I'll never abandon it.\"", objectives = "Water spray dampens the air, the view is incredible.", completion = "A campfire is newly fed with wood, but signs of a quick departure are evident." }
WordHunterWoW_QuestEN[79976] = { title = "This Must Be The Place", description = "\"So, I've decided to take my work back underground. To stop it falling into the wrong hands.\"\n\n<The paper is torn just large enough to fit the message. You aren't sure if these are the last words you'll read from the author, or if they're a clue to the next hideout. An inadequately secured sleeping bag is unrolling itself onto your feet...>", objectives = "Whoever was here, you just missed them.", completion = "Heavy canvas is rolled over assorted equipment. You help yourself to the pack." }
WordHunterWoW_QuestEN[79980] = { title = "Scramble", description = "\"Not so bad, eh? Since you're reading this, it means my stash is still there. Take a hundred paces due north and don't break your ankles going down the steep cliffside. There should be enough to keep you going.\"", objectives = "Find what awaits you.", completion = "You pull a messenger bag out of the ground. Stuffed in with the supplies is a dirty parchment." }
WordHunterWoW_QuestEN[80001] = { title = "Rekindle", description = "", objectives = "An extinguished fire pit. The wood is even dry enough to catch a flame.", progress = "An extinguished fire pit. The wood is even dry enough to catch a flame.", completion = "You put your scout skills to work." }
WordHunterWoW_QuestEN[80325] = { title = "The Mad King", description = "You find a dirty, tattered notebook full of scribbled schematics and notes. It's quite clear even after just a cursory glance that any of these creations could be used to wreak terrible havoc should anyone ever be foolish enough to build them.", objectives = "Bring Thermaplugg's Engineering Notes to Nogg at the Valley of Honor in Orgrimmar." }
WordHunterWoW_QuestEN[80411] = { title = "The Talisman of Kazdor", description = "From the most recent letter we intercepted, it appears the final artifact Caius desires is the Talisman of Kazdor. The letter states this talisman is somewhere inside Zul'Farrak. \n\nI want you to complete the job as per Caius' instructions, as not to arouse his suspicion. This means you'll have to go into Zul'Farrak alone, as usual.  \n\nHowever, before you deliver the Talisman, bring it back here. We'll be giving Caius a little more than he asked for.", objectives = "Find The Talisman of Kazdor inside of Zul'Farrak. Then, bring it to Fahrad at Ravenholdt Manor. You must complete the job alone." }
WordHunterWoW_QuestEN[80526] = { title = "Fool Me Twice", description = "Not a moment too soon, {name}\n \nThe manor has been keeping tabs on this \"C\" character you've been dealing with. \n \nC's true identity is Caius Blackwood; a powerful magic user working with the Syndicate. Our sources say he has been gathering artifacts for an unknown purpose. Only recently did we discover *you* were the one providing them.\n \nCaius must be stopped, and I believe the onus of doing so falls on you. Fortunately, I've devised a plan. Come speak to me when you're ready to clear your name.", objectives = "Speak to Fahrad when you're ready to hear his plan." }
WordHunterWoW_QuestEN[81570] = { title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a moonsteel broadsword.  I call it a swing blade.\n\nYou help me?  Maybe you find it in town, maybe you talk to a blacksmith and he'll make it special.\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", objectives = "Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh." }
WordHunterWoW_QuestEN[81730] = { title = "Duskwood Mission I: Defeat Worgen", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion in the Rotting Orchard. Defeat worgen there and return to me.", objectives = "Defeat 10 Nightmare Runners and 10 Nightmare Weavers in the Duskwood Nightmare Incursion in the Rotting Orchard and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81731] = { title = "Duskwood Mission II: Defeat Ogres", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Defeat ogres there and return to me.", objectives = "Defeat 3 Deranged Ogres and 3 Demented Fire Weavers in the Duskwood Nightmare Incursion at the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You've dealt with the ogres?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
