WordHunterWoW_QuestEN[81745] = { title = "Duskwood Mission XVI: Rescue Kroll Mountainshade", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Find the sleeping Druid of the Claw Kroll Mountainshade there and escort him to safety. Then return to me.", objectives = "Rescue Kroll Mountainshade from the Duskwood Nightmare Incursion in the guest house at the Rotting Orchard and return to Field Captain Palandar.", progress = "You rescued Kroll?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81746] = { title = "Duskwood Mission XVII: Rescue Alara Grovemender", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Darmstead. Find the sleeping Druid of the Claw Alara Grovemender there and escort her to safety. Then return to me.", objectives = "Rescue Alara Grovemender in the Duskwood Nightmare Incursion in the stable at the Yorgen Farmstead and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81747] = { title = "Duskwood Mission XVIII: Rescue Elenora Marshwalker", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Find the sleeping Druid of the Claw Elenora Marshwalker there and escort her to safety. Then return to me.", objectives = "Rescue Elenora Marshwalker in the Duskwood Nightmare Incursion in the ruins of a farmhouse near the Vul'gol Ogre Mound and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81762] = { title = "Some Good News", description = "Greetings, {name}. I have good news. I've made contact with my friend, and I am leaving soon to meet with him. What's more, another orb has surfaced in Kalimdor.  I cannot be in two places at once so if you are willing, I'd like for you to go in my stead to follow up on this new orb. Speak with Katherine for further instructions.", objectives = "Speak with Katherine the Pure at the Cathedral of Light in Stormwind." }
WordHunterWoW_QuestEN[81764] = { title = "The Mysterious Merchant", description = "Well met again, {name}. Shaw and his spies have provided us with information on a mysterious merchant who just arrived in Kalimdor and is looking to offload a collection of dangerous artifacts. We've come to believe that he has an Echoing Orb in his collection. He is staying at the Theramore Inn in Dustwallow Marsh. Travel quickly, retrieve the orb, and speak to no one of this. We are sending you in alone to avoid drawing the attention of our enemies. \n\nBe safe, and go with the light.", objectives = "Travel to Theramore and find the mysterious merchant." }
WordHunterWoW_QuestEN[81765] = { title = "Elrick, Paladin of the Silver Hand", description = "<The Paladin standing before you is not known to you. Speak with him to determine what he knows of the merchant and the current situation.>", objectives = "Speak with Elrick to learn more." }
WordHunterWoW_QuestEN[81766] = { title = "The Bloody Missive", description = "<You find a missive on the body of the \"paladin\". It is covered in blood and difficult to read, but you can make out the message on the parchment.\n\nIt's clear upon reading the note that this entire venture to find the \"merchant\" was a trap. You should return to Katherine for further instructions.>", objectives = "Bring the missive to Katherine the Pure at the Cathedral of Light in Stormwind." }
WordHunterWoW_QuestEN[81768] = { title = "Ashenvale Mission I: Defeat Satyrs", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Bough Shadow, and journey to the Nightmare Incursion in Satyrnaar. Defeat satyrs there and return to me.", objectives = "Defeat 10 Dreamfire Betrayers and 10 Dreamfire Hellcallers in the Ashenvale Nightmare Incursion in Satyrnaar and return to Field Captain Hannalah." }
WordHunterWoW_QuestEN[81769] = { title = "Ashenvale Mission II: Defeat Treants", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Bough Shadow, and journey to the Nightmare Incursion at the Warsong Lumber Camp. Defeat treants there and return to me.", objectives = "Defeat 7 Vengeful Ancients in the Ashenvale Nightmare Incursion at the Warsong Lumber Camp and return to Field Captain Hannalah." }
WordHunterWoW_QuestEN[81771] = { title = "Ashenvale Mission IV: Dragon Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Bough Shadow, and journey to the Nightmare Incursion in Forest Song. Retrieve an intelligence report from Dreamwarden Ellodar there and return to me.", objectives = "Gather intelligence from Dreamwarden Ellodar in the Ashenvale Nightmare Incursion in Forest Song on the bridge to the ancient tower and return to Field Captain Hannalah." }
WordHunterWoW_QuestEN[81772] = { title = "Ashenvale Mission V: Satyr Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Bough Shadow, and journey to the Nightmare Incursion at Satyrnaar. Retrieve an intelligence report from Dreamwarden Mandoran there and return to me.", objectives = "Gather intelligence from Dreamwarden Mandoran in the Ashenvale Nightmare Incursion at the ritual circle in Satyrnaar and return to Field Captain Hannalah." }
