WordHunterWoW_QuestEN[81872] = { title = "Feralas Mission XVI: Rescue Mellias Earthtender", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at Oneiros. Find the sleeping Druid of the Claw Mellias Earthtender there and escort him to safety. Then return to me.", objectives = "Rescue Mellias Earthtender from the Feralas Nightmare Incursion at the stairs by Jademir Lake in Oneiros and return to Field Captain Arunnel." }
WordHunterWoW_QuestEN[81885] = { title = "The Ritual", description = "I wanted to thank you for your efforts, {name}. Without you, I'd likely be dead and the servants of the legion would still have possession of this dangerous artifact. I know its difficult to trust an agent of the Lich King, but it is my hope that after this is over we can sway my friend back to the light. It's clear that the man I cared for is still in there. He may only need a nudge.\n\nCome now, we are needed by Gregory to help him complete the ritual. Let us speak again when it's done.", objectives = "Speak with Gregory to begin the ritual." }
WordHunterWoW_QuestEN[81900] = { title = "The Burning Beast", description = "<The carving before you depicts a two-headed beast emerging from the Dark Portal. Fel-fire spews forth from its mouths. A plaque beneath the image reads: \"Calefactus the Unleashed\". \n\nIntuition tells you the Twilight cultists may have plans to harness this creature's destructive power for their own aims.\n\nYou reason that the next step in your hunt is towards the Blasted Lands. Someone there may know more of this hellish beast.>", objectives = "Find an expert on the beasts of the Blasted Lands." }
WordHunterWoW_QuestEN[81917] = { title = "Chains That Bind", description = "I have seen this creature you call \"Calefactus\" many times in my field studies. By all accounts, it appears to be a nigh-invulnerable core hound made from Fel energies.\n\nHowever, if what you say is true, and the Twilight's Hammer were planning to enslave it, then there may be a way to subdue the beast.\n\nThe Shadowsworn, to the south-east, are known to perform dark rituals, including the enslavement of Fel creatures. Perhaps members of their order carry a clue to weakening Calefactus?", objectives = "Bring 5 infernal chain links to Bloodmage Lynnore in the Blasted Lands" }
WordHunterWoW_QuestEN[81919] = { title = "Brought to Heel", description = "I have fashioned a tool from the chain links you found. You might call it a \"lasso\" of sorts.\n \nThe energy within this chain is best suited for binding demons, but seeing as Calefactus may be from beyond the dark portal, I suspect it will work on him as well.\n\nIf you take him down bring me a sample of his fel lifeblood. Such an anomalous being warrants further study.\n\nCalefactus' current location among these wastes is unknown, but I trust you'll track him down, {class}.", objectives = "Bring the fel lifeblood of Calefactus the Unleashed to Bloodmage Lynnore in the Blasted Lands" }
WordHunterWoW_QuestEN[81924] = { title = "Wisdom of the Guardians", description = "Whatever Kaldorei knowledge you seek will not be found among these ruins, {class}. Not anymore.\n\nHowever, while the physical lies in ruin, the spiritual remains.\n\nSeek the guardian spirits of Azshara, the Hinterlands, and Feralas. You will know them by their shrines. Prove yourself to them, and heed their words. Their wisdom will be passed on to you, so that it will not be lost to time as so much was here.", objectives = "Prove yourself to the guardian spirits of Feralas, Azshara, and the Hinterlands, then return to Tyrisius in Feralas." }
WordHunterWoW_QuestEN[81944] = { title = "A Newly Discovered Purpose...", description = "", objectives = "" }
WordHunterWoW_QuestEN[81947] = { title = "Sanguine Sorcery", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
