WordHunterWoW_QuestEN[82062] = { title = "Ever After", description = "Had to be sure we could trust you. These kind of friends are hard to come by. \n\nThere's a malignancy growing, a sinister faction within Azeroth. Both the Horde and Alliance are unwittingly working towards their own ends. Slowing their advances and forming information networks are all we have resources for.\n\nTake this, raise your spirits, and harken back to better days. There will be a time soon where we need our bolstered numbers for a show of force.", objectives = "Speak with the Rugged Traveler." }
WordHunterWoW_QuestEN[82068] = { title = "Fight the Nightmare Incursions", description = "Complete a Nightmare Incursion mission in Feralas or Hinterlands today and you'll earn an extra reward.", objectives = "Complete a Nightmare Incursion mission in Feralas or Hinterlands and then report to Field Captain Korlian or Field Captain Arunnel." }
WordHunterWoW_QuestEN[82084] = { title = "A Lesson in Literacy", description = "Your progress in the arcane arts has been exemplary, {name}. I think you are ready to author a spellbook of your own.\n\nLet's see... a quill from the Owlbeasts of the Hinterlands, and ink derived from silithid resin... yes, that will do. And for the pages, the finest Farraki Papyrus!", objectives = "Track down and collect the spellbook materials requested by the librarian." }
WordHunterWoW_QuestEN[82135] = { title = "The Price of Hope", description = "<Aeonas says nothing, he merely hands you the orb and turns away>", objectives = "Bring the Mannoroc Echoing Orb to Katherine the Pure in Stormwind." }
WordHunterWoW_QuestEN[82208] = { title = "Greater Friend of the Library", description = "", objectives = "Thanks to your donations, the library is thriving.\n\nPlease, take this." }
WordHunterWoW_QuestEN[83934] = { title = "Show Me the Money!", description = "Heya! You look like the \"resourceful adventurer\" type so maybe you can help me out. See, my brothers and I came from Kezan looking to start up a new business venture but we ran afoul of some pirates who stole our startup money. The people who are funding our operation back home aren't exactly what I'd call understanding, so we'd make it worth your while if are able to find any of the coin and return it. It's no ordinary gold but you should know it when you see it.", objectives = "Bring a Tarnished Undermine Real to Pix Xizzix in Booty Bay." }
WordHunterWoW_QuestEN[84135] = { title = "Beach Bot", description = "Lying on the shore, half-lost in the afternoon spray, is a strange metal contraption. It looks like some kind of mech, but you have never seen anything like it before. You notice a label on its side that reads \"Property of D.E.L.T.A.: Deepsea Exploration and Liquefaction Technologies Alliance\". You also spot a small compartment that you might be able to open.", objectives = "Use a rock or something to dislodge parts of the mech." }
WordHunterWoW_QuestEN[84137] = { title = "Mechanical Romance", description = "You wonder why this mech was crashed here, and what this liquid is for. Maybe you can use it to reach the nearby islands and oil rig that seem to be connected to this mysterious organization. Opening the vial, a mildly intoxicating fruity aroma greets your nose.", objectives = "Find a use for the Guided Buoyancy Accelerant" }
WordHunterWoW_QuestEN[84138] = { title = "Frosty Favors", description = "I'm the chief engineer, founder and lead researcher of the Deepsea Exploration and Liquefaction Technologies Alliance. I've nearly finished my latest experiment, and I need your help! I am working on a special device to geolocate resource-rich dimensions.\n\nTo complete my construction, I need something back: a book of arcane formulas that I lent to an old colleague of mine, Nami, who continues her work in Winterspring.\n\nRetrieve the book for me and you'll be included as a published contributor!", objectives = "Explain the book situation to Doctor Jurgens' colleague, Nami, in Winterspring." }
WordHunterWoW_QuestEN[84146] = { title = "Red Bag Blues", description = "What you want is safely hidden, and I can only hope the same can be said for what I'm looking for.\n\nI had a red bag containing some valuable tooling that I use for electro-optics. But, I lost it in a zeppelin accident over Burning Steppes! The bag could still be there, but with orcs, ogres, and poachers, I've had to put my work on hold.\n\nIf you can locate it and bring it back to me, I'll let you have Jurgens' old book.", objectives = "Locate the Red Bag that Nami in Everlook lost in a zeppelin mishap over Burning Steppes." }
WordHunterWoW_QuestEN[84147] = { title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge." }
WordHunterWoW_QuestEN[84148] = { title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Deliana in Ironforge." }
