WordHunterWoW_QuestEN[84211] = { title = "Poacher's Den", description = "Picking up the bag, you immediately notice it's nearly empty. Somehow you get the impression Nami wont trade the book for the bag by itself. But what's not empty, is the camp. You'd better defend yourself and keep your eyes peeled for more of this stuff.", objectives = "Recover the rest of the materials and return to Nami in Everlook." }
WordHunterWoW_QuestEN[84212] = { title = "Bookin' it Back", description = "Nami hands over Jurgens' book. With it safely stowed, you begin the long journey back to the other side of the world.", objectives = "Return to the D.E.L.T.A lab with the book Jurgens was looking for." }
WordHunterWoW_QuestEN[84213] = { title = "Rift Away", description = "Join me in this historic experiment and witness the wonders of my invention! I've calculated two locations with suitable geothermic bioflux energy. With manual-auto-locking phasers, I'm ready to send us to the coordinates within compatible regions.\n\nOnce you're at compatible coordinates, use this remote transponder to send the signal to me. I'll configure the warp transmitter to fold the space between here, and there.\n\nWhat I'm saying is, I'll meet you there when you say you're ready!", objectives = "Use the Distant Communication Device to send the signal to Jurgens at either Tirisfal Glades or Westfall\nThen, assist him in demonstrating the capabilities of his elecro transmitter." }
WordHunterWoW_QuestEN[84318] = { title = "Oi!", description = "Oi! {class}! Yes, ye! Ye did me a solid by smashing up that depressin' mess of a meatsuit I've been riding in all these years, but I dinnae feel much of a pull to move on. I'm expectin' it's because I got some \"Unfinished Business\" to get up to 'afore I can be on me way. Well dull-wit, ye just been conscripted to help!\n\nI need ye to fetch me hammer. Should be somewhere in Corrin's Crossing and it'll be hard to miss. \n\nOi, take this too. It's me favorite gold tooth. Give it a rub when you've found me weapon.", objectives = "Find Orthas' missing hammer in Corrin's Crossing." }
WordHunterWoW_QuestEN[84319] = { title = "Oh No Ye Don't!", description = "Great job with the hammer, {class}. Next up is me armor. Definitely need that back to move on to the great beyond.\n\nOnly problem is it's in the eh... innards o' one of them abominations. I know, I know, it's askin' a lot, but ye gotta understand I was once a mighty thane under the mountain! I simply can't move on knowin' that the ancestral armor of me clan is dissolving in the gutjuice of a giant rotting mountain o' meat!", objectives = "Orthas needs you to recover his missing armor from the corpse of an Abomination somewhere in Plaguewood." }
WordHunterWoW_QuestEN[84330] = { title = "A Wee Bit O' Necromancy", description = "So ye see, we need to find a suitable Dwarf corpse and do a bit o' ritual to em' to get my spirit grounded so I can be sent on me way! All perfectly normal stuff, o' course! We'll also need a bit o' Necrotic Runestone from a necromancer type, of course. There's one in Stratholme that goes by Maleki the Pallid. Can't expect he'll be too willin' to part with it willingly but there's a solve for that!\n\nGet me that stone and then head to the undercroft. There's a corpse there that'll do!", objectives = "Obtain a Necrotic Runestone from Maleki the Pallid in Stratholme, then find the Rotting Dwarf Corpse near the Undercroft in southwestern Eastern Plaguelands." }
WordHunterWoW_QuestEN[84332] = { title = "A Thane's Gratitude", description = "<You hear a disembodied voice in your head as you touch the small chest> \n\nCan't be thankin' ye enough, {name}. Not how ye'd be expecting it to turn out, no doubt! Just so you aren't too sour about it, I've got something for ye that I've no more use for that I think ye might find useful.\n\nGood luck to ye, {name}. Ah, one last thing... if ye happen to see a giant floating necropolis in the distance someday soon, I'd be turnin' tail and runnin' if I were ye. Hah!", objectives = "" }
WordHunterWoW_QuestEN[84395] = { title = "Undead Potatoes", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
