WordHunterWoW_QuestEN[84414] = { title = "Send Me On Me Way", description = "<You hear the disembodied voice of Orthas in your mind>\n\n'Ere we are then. Let's get on with it, shall we?", objectives = "Observe Orthas as he moves on from this world." }
WordHunterWoW_QuestEN[84555] = { title = "Nostro's Compendium", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.", objectives = "Return Nostro's Compendium of Dragon Slaying to the Athenaeum." }
WordHunterWoW_QuestEN[86574] = { title = "Stonetalon Supply Run", description = "<The unfortunate body here bears the marks of many strikes from the Pridewing wyverns. The pack nearby is rumpled and discarded, with its contents missing, and only a small note clutched in the courier's hand to indicate what was lost: a shipment meant for Innkeeper Faralia at Stonetalon Peak.>\n\n<The wyverns have probably carried off the supply bundles to line their nests.>", objectives = "Collect 1 Stonetalon Supplies from Pridewing Wyverns and deliver them to Innkeeper Faralia.", progress = "I hope that shipment comes soon...", completion = "You found the missing shipment?\n\nOh, I had no idea that the courier didn't make it. That is... a tragic state of affairs...\n\nI'll put these supplies to good use to make sure that her loss is not in vain." }
WordHunterWoW_QuestEN[86576] = { title = "Bloodfury Trinkets", description = "In addition to spreading their filth across the Charred Vale, the Bloodfury harpies gather anything shiny that they can find. I'm told that they collect a variety of golden-yellow sunstones for decoration. I have no use for such trinkets, but Mor'rogal has mentioned using them before.\n\nWhile you're fighting the harpies of the Vale, keep your eye out for Glittering Sunstones. Bring any that you find to Mor'rogal, up on the hills above us.", objectives = "Bring 15 Glittering Sunstones to Mor'rogal.", progress = "I have important matters to consider, {class}. Be quick.", completion = "Ah, you have brought sunstones that the harpies collect! The harpies love to gather objects that are shiny, but they do not know the true value of the stones. By capturing the dazzling light of the sun, these stones reflect its majesty and allow us to adorn our shrines and homes with tiny motes of light in its honor. The moon, too, illuminates them with its silver beauty at night.\n\nThese stones remind us of the connection we have to the lights of the skies." }
WordHunterWoW_QuestEN[86577] = { title = "A Sampling of Putrescence", description = "The corruption that rains down from Hyjal flows through the mountain's waters and seeps into everything here in the wood. The creatures that drink the water take the corruption into themselves. It makes them ferocious, diseased, and fearless.\n\nTo counter these effects, I must understand them, and to do that I need samples from the afflicted.\n\nA few samples of putrescent organs from the wolves and bears should do. Take your time; the creatures are common here in Felwood.", objectives = "Bring 8 Putrescent Bear Organs and 10 Putrescent Wolf Organs to Kelek Skykeeper." }
WordHunterWoW_QuestEN[86585] = { title = "Banner of the Fallen", description = "The fallen mountaineer bears a standard of Ironforge. Perhaps she was scouting, or making a doomed charge. Either way, the standard has been cast down and trampled. The mountaineer was hit on the head so hard that her helm was knocked off and she was killed outright by a trogg, likely with a spiked club.\n\nThe trogg that killed her is probably still nearby, and likely remembers the banner. Raising the banner of Ironforge once more may call it out.", objectives = "Raise the standard of Ironforge, call out the trogg Headsplitter and kill it, then report to Captain Rugelfuss.", progress = "That banner looks like it's been in a war!", completion = "You found Ylva's body? Ah, the poor woman. She said she was going to show the troggs that Ironforge would never fall to their kind. She went looking for a few mountaineers who never returned from a patrol through trogg country. She was always too independent-minded to be cautious. Now we know what happened.\n\nI'll take the banner back and make sure it's cleaned up and displayed. You should take her weapon. May it serve you well against the troggs." }
WordHunterWoW_QuestEN[86611] = { title = "Stag Lord's Bauble", description = "<The pool of fetid slime has eroded the statue of the stag. It is unclear how it arrived here at the bottom of the lake.\n\nA single crystal stone set in a medallion around its neck bears an unwholesome green gleam. It is worth taking to someone who might know the history of this monument.>", objectives = "Take the Stag Lord's Bauble to someone in Talonbranch Glade who may know about it." }
WordHunterWoW_QuestEN[86612] = { title = "Stag Lord's Bauble", description = "<The pool of fetid slime has eroded the statue of the stag. It is unclear how it arrived here at the bottom of the lake.\n\nA single crystal stone set in a medallion around its neck bears an unwholesome green gleam. It is worth taking to someone who might know the history of this monument.>", objectives = "Take the Stag Lord's Bauble to someone in Bloodvenom Post who may know about it." }
WordHunterWoW_QuestEN[86613] = { title = "Excavation Tools", description = "The excavation's tools, left behind when the dwarves fled from the troggs, seem mostly untouched. Returning them to the excavators will surely aid their work.", objectives = "Return 6 Excavation Tools to Magmar Fellhew.", progress = "We just, uh, need to adjust our dig site and we can get this whole thing back on track!", completion = "Our tools!\n\nWhen the troggs overran the camp, we had to leave most of our tools behind. This'll be a big help once we get this invasion under control and can start working again!" }
WordHunterWoW_QuestEN[86614] = { title = "Silver of the Waves", description = "<Among the fishing knickknacks in the debris are some rusty hooks, broken spools of wire, and a slightly corroded but ornate silver hair clip with the monogram \"K.D.\">", objectives = "Return the Monogrammed Silver Hair clip to its owner.", progress = "I have a lot of chores today, so can you keep it quick?", completion = "My hair clip! I thought this was lost for good!\n\nThis'll shine right up with just a little work. Thank you for bringing it to me! I'll make it worth your while." }
WordHunterWoW_QuestEN[86615] = { title = "Treaty Obligations", description = "Ach! Here I am serving as ambassador to the Wildhammers, and I left me satchel of the latest diplomatic missives somewhere in Wildhammer Keep. I must've left it in the tavern... or maybe I misplaced it by the steam tanks... or was it upstairs? I can never keep track!\n\nI need those papers! If you have a better eye for the keep than I do, see if you can spot my missing diplomatic satchel!", objectives = "Find Ambassador Redstone's missing diplomatic satchel in Wildhammer Keep." }
WordHunterWoW_QuestEN[86616] = { title = "Repurposed Totems", description = "As a shaman, one of the challenges of communing with the elements is that there are other shaman with opposing agendas. The elements do not care why we do what we do, they just do as we ask!\n\nThe trolls at Jintha'alor also practice the shamanic arts, and their interruptions and attacks are a constant thorn to us here.\n\nFind their Vilebranch totems and bring them back to me so that I can nullify their powers. Some they carry, some they place as wards around their altar.", objectives = "Bring 12 Vilebranch Totems back to Maret Firetend." }
WordHunterWoW_QuestEN[86620] = { title = "Fledgling Rescue", description = "Though we have a good line of gryphons here, there are always a few egg clutches in the wild that are in danger of not making it. A gryphon parent can lose a fight against a wolf, or fall sick. Without help, the fledglings will never survive.\n\nFortunately, we have the means to raise and protect lost young ones like this. If you find lost eggs in the wild, bring them to me.", objectives = "Collect 6 Lost Gryphon Eggs for Gryphon Master Talonaxe." }
WordHunterWoW_QuestEN[86667] = { title = "Snowbound", description = "My old mentor, Norric, sent a minor elemental with an odd request. He needs a jar of snow for some of his shamanic workings! I don't know what he's going to do with that, but I learned a long time ago not to question his ways with respect to magic.\n\nI'm busy learning about the local elementals, so I can't leave to help him. Go to the tunnel entrance at South Gate Pass where there's snow year-round. Scoop some up in this ceramic jar and bring it to him before it melts. The jar should keep it cold.", objectives = "Deliver a Jar of Snow to Norric Lochthane at his house on the northwest coast of the Loch.", progress = "Eh? What do you want?", completion = "This jar is for me?\n\nSnow! Grenhild did it! She sent the snow that I asked for!\n\nA pity, though, I was hoping she would come and visit in person.\n\nWell, regardless, thank you for your effort. This is a real help for my work." }
WordHunterWoW_QuestEN[86746] = { title = "The Legashi Threat", description = "My people are struggling, {name}. \n\nThe Legashi satyr have invaded our den, corrupting many of the Blackmaw and separating us from our Timbermaw allies. Those of us who survive their attacks are huddled in makeshift camps. Worse still, the satyr's corruption is spreading across the land, and poses a threat to my already vulnerable tribe.\n\nThe Legashi lurk among the ruins northeast of here. I must ask you for help in defeating them.", objectives = "Kill 5 Legashi Satyr, 5 Legashi Rogues, and 5 Legashi Hellcallers for Ekkal at the Ruins of Eldarth." }
WordHunterWoW_QuestEN[86752] = { title = "Report to Rageroar", description = "There is much more to be done in our fight against the satyr, {name}.\n\nIf you wish be of further help, speak with Gatekeeper Rageroar at the camps of Ursolan to the north. He will know where to use your abilities best. You should find Ursolan to the north of here.", objectives = "Speak with Gatekeeper Rageroar at Ursolan." }
WordHunterWoW_QuestEN[86757] = { title = "Slowing the Orc Advance", description = "Orcs have taken over the eastern forest, and their scouts and grunts now lurk throughout the woods! It's not safe for our kind to move about Ashenvale any more.\n\nWe need to push back the orcs and secure the forest. We've been able to pick off some of the grunts and scouts by carefully sneaking around the edges of their camp.\n\nFight the orcs and bring me the jagged swords and curved knives that they use. I'll make sure their weapons are salvaged and repurposed, so nothing goes to waste.", objectives = "Bring 6 Jagged Orc Swords and 4 Curved Orc Daggers to Shandrina.", completion = "Excellent work, {name}.\n\nI deplore the situation that requires us to resort to this kind of violence, but if the orcs aren't stopped, they'll invade Astranaar and cut down the whole wood. At least we can reuse the metal of their crude weapons to make defenses of our own." }
WordHunterWoW_QuestEN[86758] = { title = "Twisting the Knife", description = "Did I ever tell you how I almost lost me hand to a crocolisk? Managed to jam me knife into its jaw, and scrambled out real quick. I thought I had the knife around here somewhere, but I can't seem to find it.\n\nAnyway, that croc is probably still out there hunting along the edge of the lake. That nasty brute probably needs to go, for the safety of the other hunters, if nothing else.\n\nI've taken to calling it Daggerfang. If you see it, give it a friendly hello from me! And by \"hello\" I mean \"stab.\"", objectives = "Find and defeat the crocolisk Daggerfang and bring back Marek's knife.", progress = "How goes the huntin'?", completion = "Hah! You did it! I never thought that ol' croc would get its comeuppance, but that does the trick!\n\nOh ah... y'know, I had to get me another knife, but maybe that one will bring you some good luck. Why don't you hang onto it?" }
WordHunterWoW_QuestEN[86776] = { title = "Ingredients for the Forge", description = "Thelsamar's a great place to live, but we don't have all of the amenities of Ironforge. I'm always running out of bronze! I need more bronze if I'm going to keep making tools and kettles and pots!\n\nI can tell you have a little experience at the forge. Think you could smelt me some bronze bars? I can pay you well for it!", objectives = "Bring 10 Bronze Bars to Morhan Coppertongue.", progress = "Gotta keep the forges going!", completion = "Ah, this is a relief! I should be able to keep the forge going now. Hopefully one of these days we'll get a trader bringing coal into town regularly!" }
WordHunterWoW_QuestEN[86777] = { title = "Master Feardred", description = "Many satyr corrupt Azshara, but none are as terrible as the Legashi. Led by Varrox Bleakhoof, their camps litter the northern peninsula. They have driven us from our homes, and I fear they will ransack Ursolan before long.\n\nWe must strike back if we are to have any chance of survival.\n\nMaster Feardred, a servant of Varrox, oversees a nearby camp to the south. You can see it from here. Feardred is a key target in weakening Varrox's forces. Kill him, and bring me his amulet.", objectives = "Kill Master Feardred, and bring his amulet to Korsa." }
WordHunterWoW_QuestEN[86784] = { title = "Sticks and Bones", description = "My associate Eleanor Shackleton prides herself on traveling the wilds, surviving against weather and monsters. She is currently camped not far from here, in the hills to the west, and I remember a piece of advice that she once gave me: \"When you think you have enough firewood, gather five times more.\"\n\nIf you have some spare time, you could collect some wood in this basket and take it to her camp. I'm sure she could give you a few tips about the existence of a traveling adventurer.", objectives = "Collect 6 Dry Branches and bring them to Eleanor Shackleton.", progress = "Welcome to my fire, traveler.", completion = "Extra firewood? That is always welcome. It will keep these old bones warm through the cold nights of the Glades.\n\nI have a sling for collecting wood myself, so you might as well hang onto that basket." }
WordHunterWoW_QuestEN[86791] = { title = "Missing Blackmaw Scouts", description = "Not long ago I sent a party of scouts to gather information on the Legashi stronghold and possibly find our chieftain. They have yet to return. I am beginning to fear the worst.\n\nThe Legashi have many camps to the east of here. If any members of the party are still alive they are likely somewhere nearby.", objectives = "Find the Blackmaw scouting party near the Legashi camps east of Ursolan." }
WordHunterWoW_QuestEN[86792] = { title = "Thinning Their Forces", description = "The satyr within the Legashi stronghold are even more fearsome than those of the outer camps. When our party was discovered, we found ourselves overwhelmed.\n\nOne of us was slain, and another captured. I was the only one able to successfully retreat. I cannot return to Rageroar with my head hung in shame, but I cannot fight the Legashi alone, either.\n\nI ask you, then, to assist me in weakening the satyr's forces. Go into their stronghold and slay them.", objectives = "Kill 6 Legashi Hellraisers, 2 Legashi Soulstealers, and 4 Legashi Blackguards for Korsa outside Legashi Stronghold." }
WordHunterWoW_QuestEN[86796] = { title = "Later, Satyr", description = "You there, {race}!\n\nThese fiends ambushed my scouting party, and have taken me captive. I don't know what plans they have for me, but I don't intend to find out. I must escape and return to Ursolan; no doubt Korsa is worried about me.\n\nWhile I would love to break out of this cage and leave a trail of satyr corpses in my wake, I'm afraid I'm slightly outnumbered.\n\nPerhaps you share my hatred for the fiends, and would help me escape?", objectives = "Help Graal break out of Legashi Stronghold, then inform Korsa outside Legashi Stronghold." }
WordHunterWoW_QuestEN[86797] = { title = "Return to Rageroar", description = "With the Legashi stronghold weakened, we can return to Ursolan in honor.\n\nGo ahead of me, and inform Gatekeeper Rageroar of the situation here.", objectives = "Return to Gatekeeper Rageroar at Ursolan." }
WordHunterWoW_QuestEN[86798] = { title = "Timbermaw Reinforcements", description = "With the satyr weakened, now is the time to mount a counter-offensive. Prince Halanox, commander of the Legashi Stronghold, will be our target. However, we still lack the numbers to face him head-on.\n\nSince the Legashi drove us out we have been cut off from the furbolgs of Timbermaw Hold. We could call upon them for reinforcements, but we will need an emissary. You will be that emissary, {name}.\n\nGo to Timbermaw Hold and find a furbolg named Gorn One Eye. He will provide us with the soldiers we need.", objectives = "Speak to Gorn One Eye in Timbermaw Hold and ask him to provide reinforcements." }
WordHunterWoW_QuestEN[86799] = { title = "Encroaching Corruption", description = "<Furze lets loose an ugly, hacking, cough.>\n\nHear me, {race}, I haven't much strength to speak. I am stricken by an illness unlike any I have ever known. It is as if my blood itself is aflame, and my very essence is coming undone. I can hardly move, much less fetch help.\n\nPlease, go find Elder Bramblesnap. Her tent is just northwest of here. She will know what to do.", objectives = "Speak to Elder Bramblesnap about Furze's illness." }
WordHunterWoW_QuestEN[86804] = { title = "An Unlikely Source", description = "Furze is not the first with his affliction. Since the Legashi's attacks against us began, many Blackmaw have presented with a similar illness. Each one eventually fell to corruption, becoming mindless and destructive.\n\nI have been working towards a cure. My studies indicate that one could possibly be made by transmuting the Legashi's own firewater, but I cannot acquire it myself.\n\nYou might find firewater, or a way to brew it, in the Legashi camps to the east. You would be a great help in doing so.", objectives = "Find a way to get Legashi Firewater in the Legashi Encampment." }
WordHunterWoW_QuestEN[86812] = { title = "Transmuted Tincture", description = "I have transmuted the firewater into a tincture which I believe will be the key to undoing the Legashi's corruption. Eager as I am to ease the suffering of the Blackmaw, it must be tested.\n\nI have seen many of the coursers and skystormers east of Ursolan suffering from the satyr's corruption. They will serve as our test subjects.\n\nGo, and test my would-be cure on the afflicted beasts. Before giving the tincture the beast must be weakened to ensure it can be administered with little resistance.", objectives = "Use the Satyrweed Tincture on 3 Mosshoof Coursers or Thunderhead Skystormers after weakening them." }
WordHunterWoW_QuestEN[86813] = { title = "Potential Panacea", description = "I must say, {class}. I have not felt this optimistic in some time. This tincture could be the panacea that saves us from the satyr's ever-expanding blight. Even if we remain in these camps for the rest of our lives we will stand strong and free of corruption.\n\nGo to Furze and give him this panacea. He has suffered for long enough. Return to me to report any findings.", objectives = "Administer Bramblesnap's Panacea to Furze." }
WordHunterWoW_QuestEN[86814] = { title = "Blackmaw Counter-Offensive", description = "I will send the reinforcements to Ursolan at once. \n\nTake this banner. When you are ready to face Halanox, plant it in his demonic summoning circle. This will provoke him, and signal our warriors to strike.\n\nOnce Halanox is defeated, inform Gatekeeper Rageroar.", objectives = "Plant the Timbermaw War Banner at the Legashi Stronghold in Azshara. Kill Prince Halanox, report your victory to Gatekeeper Rageroar at Ursolan." }
WordHunterWoW_QuestEN[86925] = { title = "Toil and Trouble", description = "It appears this cauldron could be used to brew the firewater that Elder Bramblesnap is after.\n\nIf only you knew how. Surely, one of the satyr in the Legashi Encampment must carry a recipe.", objectives = "Find a Legashi Firewater Recipe from satyr in the Legashi Encampment." }
WordHunterWoW_QuestEN[86926] = { title = "Felfire Burn, Cauldron Bubble", description = "The recipe reads:\n\nHarvest ye the sprout of hell\nbushel o' five will serve ye well\nmixed with mote of demon's power\nshall usher in their final hour", objectives = "Bring 5 Satyrweed and a Fel Mote to the Legashi Cauldron in the Legashi Encampment." }
WordHunterWoW_QuestEN[86927] = { title = "Running Firewater", description = "As the satyrweed and fel mote splash into the boiling liquid, a plume of noxious gas emerges.\n\nBest to hold your nose, quickly grab a sample, and bring it back to Elder Bramblesnap.", objectives = "Bring the Legashi Firewater to Elder Bramblesnap at Ursolan." }
WordHunterWoW_QuestEN[87288] = { title = "Soft Saber Pelts", description = "Hello, traveler! I hope you are enjoying your visit to our village. I like Dolanaar because it is small and rustic and everyone is friendly.\n\nI'm a local trader, and I bring in all sorts of tools and trinkets that might be useful to you in your travels. Indeed, if you are interested in a trade, I find myself in need of some nightsaber pelts. While these majestic creatures are beautiful, the local ones are rather aggressive, so don't feel too bad about defending yourself.", objectives = "Bring 6 Soft Nightsaber Pelts to Aldria.", progress = "It is good to see you again! Are you here to trade?", completion = "Oh, these are wonderful. It is a shame to resort to violence with such majestic animals, but it is important to keep the roads safe, and these pelts will make beautiful blankets and shawls.\n\nHere, let me give you something to remember them. It is both soft and sturdy." }
WordHunterWoW_QuestEN[87295] = { title = "Deflective Surface", description = "You may have seen the Redstone basilisks wandering the wastes outside while you were on your way to Nethergarde Keep. They're tough creatures, well adapted to survival in the Blasted Lands. One of their key qualities is their sturdy scales, which reflect heat, protect against sand and wind, and even deflect weapon blows!\n\nThey're a perfect material for making shields, and if you can bring me a bundle, I'll compensate you well. Only bring ones in good condition!", objectives = "Bring 10 Redstone Basilisk Scales to Bernie Heisten." }
WordHunterWoW_QuestEN[87318] = { title = "Hearts of the Lost", description = "Thandol Span has been a dangerous place since the Dark Irons blew up the bridge, but I didn't expect to run into them there!\n\nI managed to escape, but I lost sight of my partner, Essene. I've been searching all over for her, but I haven't found any sign of her. Did the Dark Irons capture her? Did she fall into the river below? Did she make it back to the other side? I don't know! I don't even know if she's alive!\n\nPlease, if you see any sign of her, let me know!", objectives = "Search for Corma's partner Essene." }
WordHunterWoW_QuestEN[87346] = { title = "Chieftain Bloodmaw", description = "When the Legashi overran the Blackmaw, the rest of the Timbermaw sealed their passage to the hold to keep out the satyr. We had no idea they lived on as refugees.\n\nI would gladly aid my brethren, but we are fighting our own battles. Like the Legashi threaten the Blackmaw, the Deadwood do likewise to us. We haven't many warriors to spare.\n\nThe Deadwood chieftain, Bloodmaw, is in Felpaw Village to the south. Eliminating him would greatly ease our struggle. Bring me his mace, and you will have our aid.", objectives = "Kill Chieftain Bloodmaw and bring his mace to Gorn One Eye in Timbermaw Hold." }
WordHunterWoW_QuestEN[87451] = { title = "Memories of Rockard", description = "This trinket, carried by the ogre, seems to be a small stone carving depicting an orc family. It may be a memento from the orcs who lived here when this was the town of Rockard, before the ogres invaded.\n\nIt probably has sentimental or spiritual value to the survivors at Stonard.", objectives = "Take the Carved Stone Trinket to Dispatch Commander Ruag in Stonard, in the Swamp of Sorrows." }
WordHunterWoW_QuestEN[87491] = { title = "Spark of Freedom", description = "Sss! The foul Dark Irons have summoned me and kept me caged next to their petty fire pit!\n\nFire must run wild, run free! Release me! Must escape! Must BURN!\n\nNo Dark Iron is safe! Burn them to the ground! Burn their black powder! Burn their fortress, their fuses, their folly!\n\nLet me out and I will BURN THEM ALL!", objectives = "Escort the captive fire elemental out of Dun Modr and to its freedom." }
WordHunterWoW_QuestEN[87492] = { title = "Uncanny Crystal", description = "You may have seen some of the unusual crystal growths that dot this crater. I'm not a miner, but these growths don't seem to fit with the kinds of soil deposits all around here.\n\nI believe I caught sight of a damaged crystal not far from here while I was foraging. I wonder if it holds any secrets about the origins of these strange formations? If you happen to spot it, I would love to investigate a sample piece.", objectives = "Bring 1 Damaged Blue Crystal back to Torwa Pathfinder." }
WordHunterWoW_QuestEN[87494] = { title = "Microcrystal Contamination", description = "This scale is slightly more reflective and iridescent than the others, as if it's embedded with tiny particles of crystal.\n\nTorwa Pathfinder might be able to make something of this.", objectives = "Take the Crystal Infused Scale to Torwa Pathfinder." }
WordHunterWoW_QuestEN[87760] = { title = "Holy Diver", description = "I have received word back from Darnassus, {name}!\n\nFrom the animal samples, we learned that the naga dominated these sea creatures to use as unwilling mounts and beasts of burden. The ones that were too obstinate, or too old or badly injured, they drove out for sport. Monstrous!\n\nIt is our sacred duty to put a stop to this!\n\nThe naga have forces in the Ruins of Mathystra, and they must be seizing threshers from off the shore. Find their beastmistress, slay her, and bring back her tools of domination!", objectives = "Find a Stormscale Beastmistress, slay her, and bring back her Rod of Deep Dominion.", progress = "We will finally have resolution to this mystery, and the animals will have peace at last!", completion = "This has been a long journey, Orangequake, but it was worth it.\n\nAt long last, you have wrested away the rod that the naga use to compel the sea creatures into their service. I will make sure it is destroyed, and the threshers and sea turtles can finally live in peace.\n\nThank you again. Your persistence has finally been rewarded, and I, personally, am grateful to you." }
WordHunterWoW_QuestEN[88756] = { title = "Bring Back a Bang", description = "The Dark Irons have a few camps east of here on Direforge Hill, and they've stolen a bunch of explosives from our construction site and hauled 'em back to their tents.\n\nI don't need tae tell ya what kinda mischief Dark Irons can get up tae with a barrel o' powder!\n\nI know the Dark Irons are dangerous, but we need those barrels back. You can tell 'em from other barrels because of the red markings on 'em. We cannae let the Dark Irons keep 'em!", objectives = "Retrieve 3 Stolen Explosives from the Dark Iron Dwarf camps.", completion = "Ach, that's a load off me mind. At least the Dark Irons won't be able to roll a bomb-cart into our wagons... or lob 'em in a trebuchet... or roll 'em down the hill at us... or feed 'em tae slimes and then let the slimes loose near are camp and set 'em on fire.\n\nNow we just have tae make sure the powder stays dry!\n\nThanks!" }
WordHunterWoW_QuestEN[88757] = { title = "Accessories of the Lost", description = "While I was fleeing from those Dark Irons, I wound up dropping lots of my gear!\n\nIt looks like I lost... my green leather waterskin, my spellbook, my necklace, and... well I need these things!\n\nIf you can find them while I repack and catch my breath, that would be a great help.", objectives = "Bring back Essene's Necklace, Essene's Spellbook, and Essene's Waterskin." }
WordHunterWoW_QuestEN[88758] = { title = "Sentiments of the Lost", description = "I just need to finish repacking, and I can get out of here!\n\nIf you'll do me one last favor, here--take this note to Corma. It'll let her know that I'm alive and I'm on my way!", objectives = "Bring Essene's note back to Corma Villard." }
WordHunterWoW_QuestEN[88807] = { title = "Slay the Spitelash", description = "Azshara may appear beautiful, but it is a cursed place. There are horrors deep beneath its waters, waiting to emerge and tear the world asunder.\n\nAll we can do for now is fight the horrors that have already surfaced.\n\nThe Spitelash Naga occupy the Ruins of Eldarath to the north east. The ones within the ruins are well-fortified, so we must pick off the weaker ones along the outskirts first.\n\nAs you can see, we could always use another fighter here, if you are up to the task.", objectives = "Kill 8 Spitelash Warriors and 8 Spitelash Screamers for Commander Truesong in Azshara." }
WordHunterWoW_QuestEN[88809] = { title = "Preserving Eldarath", description = "Millennia ago, Eldarath was a sight to behold; a living testament to the glory and might of the Kaldorei. What we call Eldarath today is hardly a pile of rubble by comparison.\n\nNonetheless, what remains is worth salvaging, if only to preserve our history. The Spitelash must be driven out before Eldarath is completely ransacked.\n\nFollowing the road north east will lead you right into the heart of the ruins. Go there, and retrieve as many of our relics as you can--and their commander's head.", objectives = "Collect 12 Eldarath Relics from Spitelash Serpent Guards, Spitelash Sirens, and Spitelash Myrmidons, and Lord Sarthiss' Head for Commander Truesong in Azshara." }
WordHunterWoW_QuestEN[88812] = { title = "Reclaiming Ravencrest", description = "I fear time may soon forget the Kaldorei house of Ravencrest. A lone, crumbling, monument is the only surviving proof of their presence here.\n\nThe monument can be found atop the cliffs at the very tip of the southern peninsula. Spitelash enchantresses there have a set of power stones which they use to channel their magic. Take this ward, and nullify them. This will cripple the Spitelash's magic, and give us an upper hand in driving them out.\n\nWhile you're at it, be sure to take out a few naga yourself.", objectives = "Kill 5 Spitelash Battlemasters, 5 Spitelash Enchantresses, and nullify the 3 Naga Power Stones near Ravencrest Monument for Commander Truesong in Azshara." }
WordHunterWoW_QuestEN[88813] = { title = "The Head of the Serpent", description = "Your final target is Warlord Krellian, the leader of the Spitelash. He cowers behind his guards in the Temple of Zin-Malor in the ruins of Eldarath.\n\nCut off Krelian's head, and his minions will be slithering back to the sea in fear. Then, finally, Azshara will belong to Kaldorei once again.", objectives = "Bring Warlord Krellian's head to Commander Truesong in Azshara." }
WordHunterWoW_QuestEN[88821] = { title = "Making Contact", description = "While scouting along the cliffs of the Shattered Strand, one of our sentinels noticed a kaldorei woman on the beach.\n\nClearly, she is not with our expedition, and she did not have the makings of a fighter. I wonder then, what she could be doing in such a hostile place as this.\n\nIf you can, try to make contact with her. I would like to know her purpose for being here, and if our interests are perhaps aligned.\n\nShe was last seen on the eastern coast, along the north side of the Bay of Storms.", objectives = "Find the Kaldorei woman last seen on the Shattered Strand." }
WordHunterWoW_QuestEN[88857] = { title = "Saving a Sentinel", description = "<The sentinel speaks in a low whisper>\n\nListen, {class}, before they hear us. I am a sentinel from Talrendis Point. The satyr here believe me injured, but I am only feigning; waiting for the moment they drop their guard and I can escape.\n\nYour arrival is perhaps such a moment.\n\nHelp me out of here, would you?", objectives = "Help Keldara Sunblade escape the Haldarr Encampment, then speak to Commander Truesong at Talrendis Point." }
WordHunterWoW_QuestEN[88884] = { title = "Highborne Tablets", description = "Just south of here, along the beach, there are some tablets of highborne writing. They document the highborne's investigations into the laws and powers of the arcane. \n\nThe tablets are being kept in pagoda-like structures, guarded by naga, so I wouldn't dare attempt to procure them myself.\n\nFortunately, I've found myself a new assistant! \n\nSo, what do you say? Think you could be of further use in the pursuit of knowledge?", objectives = "Find the three highborne tablets among the ruins of Southridge Beach, then bring them to Saria Fairmoon in Azshara." }
WordHunterWoW_QuestEN[88917] = { title = "Slithering Looters", description = "I came here in search of highborne artifacts. You could call me an archaeologist of sorts.\n\nThe ruins of Eldarath to the west hold many of them, although the naga are looting the ruins as we speak.\n\nA naga called Lady Sesspira leads the pillaging; no doubt keeping the best finds for herself. \n\nIf my research is correct, I believe she may be in possession of the staff of Archmage Selwyn, a fallen highborne mage.\n\nI need your help to get that staff, {race}. Scholars like me are ill-suited for combat.", objectives = "Find the Staff of Archmage Selwyn among the Ruins of Eldarath, and bring it to Saria Fairmoon in Azshara." }
WordHunterWoW_QuestEN[89001] = { title = "Home on the Range", description = "Greetings traveller!\n\nIf yer lookin' for a place to hang yer hat, look no further than Berdun's travel lodge! The tent's in a bit o' disrepair right now, but that can be remedied.\n\nTell ye what. If ye get me what I need to fix the tent, I'll let ye stay here for free. How's that sound?\n\nI'll need some mosshoof hides. The easiest to hunt mosshooves are just north o' here, but the hide of any mooshoof will do.", objectives = "Bring 5 Mosshoof Hides to Berdun Cliffbrew at Talrendis Point in Azshara." }
WordHunterWoW_QuestEN[89013] = { title = "Gettin' Buzzed", description = "What's a travel lodge without somethin' to drink?\n\nI can brew a fine mead, but I'm gettin' a bit on in years to gather the honey myself. There are wasp nests in the trees north of the Haldaar camp, an' west of Valormok. If ye see hippogryphs, yer in the right place.\n\nThey're nasty buggers, but the honey is like nothin' ye've ever tasted. I'll lend ye my pellet gun to knock down the hives, ye can't reach 'em otherwise.", objectives = "Gather 5 Wild Honey from Wasp Nests using Berdun's Pellet Gun." }
WordHunterWoW_QuestEN[89015] = { title = "Deadliest Catch", description = "If ye fancy yourself a real angler, there's bigger fish out here than ye can catch with a rod.\n\nMammoth Sharks lurk in the deepest waters of the northern an' southern coasts. They swim far out, right before the sea floor drops away into the great ocean.\n\nThey're mighty big; I'd advise ye take a group of anglers with ye. \n\nDwarf like me? I prefer dry land. Those sharks'd swallow me in one bite.\n\nIf ye do go hunting one, bring me a cut o' the meat. I'd be mighty thankful.", objectives = "Bring a Mammoth Shark Steak to Berdun Cliffbrew at Talrendis Point in Azshara." }
WordHunterWoW_QuestEN[89037] = { title = "Murloc Thieves", description = "On the beaches of the northern peninsula, east of here, I came upon the Tower of Eldara. While surveying the site, I noticed a large orange murloc wielding a spiked club, and carrying a peculiar glowing crystal. Given the location, it was likely the kind that the highborne used to store their history and memories.\n\nWe must recover that crystal, {race}. Who knows what secrets it could contain?\n\nThe best route to the tower is along the cliffs, with the nearest way up being just west of here.", objectives = "Take the Memory Crystal from Razorgill near the Tower of Eldara, and bring it to Saria Fairmoon in Azshara." }
WordHunterWoW_QuestEN[89038] = { title = "A Monumental Task", description = "It is said that Queen Azshara once bestowed a gift upon the kaldorei of House Ravencrest; an emblem of great beauty and magical power. This mark was given as recognition of the Ravencrests' unwavering loyalty to the queen. \n\nThe mark was last seen near the Ravencrest Monument, atop the cliffs of the southern peninsula. Securing such a relic would be the discovery of a lifetime.\n\nAs always, the ruins of the monument are crawling with Spitelash, but I trust you're rather adept at handling them by now.", objectives = "Search for the Mark of the Queen among the ruins of the Ravencrest Monument, and bring it to Saria Fairmoon in Azshara." }
WordHunterWoW_QuestEN[89053] = { title = "Your Final Reward", description = "I know you were initially sent here on reconnaissance, {name}, but you've done a great deal for the field of archaeology.\n\nSurely, after all of your toil, you'd like to know what fruits my studies will come to bear.\n\nTo that end, before you return to your camp, I'd like to show you something. Would you oblige me?", objectives = "See what Saria has to show you." }
WordHunterWoW_QuestEN[89228] = { title = "Winter Frontier Fishery", description = "Any travel lodge worth its salt's gotta have somethin' to eat.\n\nSquid are in season, and ye can fish 'em up from the coasts here in Azshara. Never was much of an angler myself, but I'm a mean cook!\n\nWhat do ye say? Feelin' some seafood?\n\nIf ye aren't much for fishin', try makin' friends with one! Or pay 'em for their goods and buy some.", objectives = "Fish up 10 Winter Squid for Berdun Cliffbrew at Talrendis Point, in Azshara." }
WordHunterWoW_QuestEN[89470] = { title = "Ill Tidings", description = "<With Saria's true intentions revealed, and a bag of powerful artifacts in hand, perhaps now would be a good time give Commander Truesong her report.>", objectives = "Bring Saria's Knapsack back to Commander Truesong at Talrendis Point." }
WordHunterWoW_QuestEN[90487] = { title = "Ancient Allies", description = "{name}, I have little more to offer. If you mean to make the long trek up the mountain, you might do well to speak with some of its ancient caretakers.\n\nFollow the road to the west. Look north, toward the foot of the mountain. You will eventually see an outpost, a remnant of the guardians that once roamed the slopes. There is an ancient there named Fraxinus. He and his friends can assist you.", objectives = "Travel west from the hermit's cave to find an outpost of ancients and dryads on the lower slopes of Mount Hyjal." }
WordHunterWoW_QuestEN[90647] = { title = "The Staff of the Mountain", description = "With all of the ingredients you assembled I was able infuse the staff you recovered with a new magic. You should now be able to bring this to bear to counteract the magic of the Wild Gods that Ve'han has so brazenly stolen.\n\nWe will need to test it, however. Bring this to the druid known as Tiala Whitemane at the Summit of Eternity. She may be able to help.", objectives = "Bring the Staff of the Mountain to Tiala Whitemane at the Summit of Eternity." }
WordHunterWoW_QuestEN[90702] = { title = "Disturbed Grave", description = "<Someone, or something, has rummaged through the dirt, leaving fragments of bone scattered about. An oddly shaped indentation leads deeper into the cold, wet dirt.\n\nSomething within the area may have caused the disruption.>", objectives = "Search the area for the grave's missing contents." }
WordHunterWoW_QuestEN[90750] = { title = "More Work?", description = "Battles are often long and hard fought, led by those willing to stand against an imminent threat and look death in the face.\n\nThe truth is, many sacrifices were made, not just on the battlefield. We often overlook those who do their part to contribute.\n\nJust yonder is a peasant by the name of... well come to think of it, I don't even know his name. What kind of person am I? He's kept us well-tended and nourished throughout our stay.\n\nCould you speak with him? Let him know the job's done.", objectives = "Speak with the peasant to let him know the job's done." }
WordHunterWoW_QuestEN[90789] = { title = "Scalebeard", description = "There isn't much time, {name}!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe beast is known as Scalebeard, hiding in a cave among the Bay of Storms. Burn him to ashes and take the prismatic shell from his den.", objectives = "Retrieve the Prismatic Shell for Archmage Xylem.  The Archmage resides in a tower atop the cliffs of Azshara." }
WordHunterWoW_QuestEN[90813] = { title = "Pay Dirt!", description = "<The large hunk of crystal is even heavier than it looks. While it appears to be quite the prize, its true nature is unknown to you. Someone with knowledge in geology could say what you've really found.>", objectives = "Find someone to appraise the Humongous Crystal." }
WordHunterWoW_QuestEN[90854] = { title = "Leather for Inclement Weather", description = "Livin' out in da wild for five years done take a toll on our supplies. We had to make dis place from scratch! We could use your skills as a leatherworker.\n\nI need to repair some of da tents and buildings, and patch up some armor. You bring me a pair of Rugged Armor Kits and a Cured Rugged Hide, I help you turn it into something special.", objectives = "Bring 2 Rugged Armor Kits and 1 Cured Rugged Hide to Zet'gan in Elderwild on Mount Hyjal." }
WordHunterWoW_QuestEN[90865] = { title = "Eyes of the Watchers", description = "Just north of here lies the ruins of battles past. A dwindling scourge presence remains.\n\nThough the mindless undead are a threat themselves, the watchers maintain a vigilant eye on those entering the area, making removal of the scourge threat even more difficult.\n\nRemove the threat by taking from these watchers that which they value most.", objectives = "Retrieve 8 Watcher's Eyes for Eluneth." }
WordHunterWoW_QuestEN[90902] = { title = "Rediscovering the Light", description = "I am proud to welcome another newly risen paladin to our ranks. As you begin to reconnect with the light you may notice that certain abilities that were once second nature to you may cause you considerable pain to use now, particularly those involving channeling the light to heal yourself or others. \n\nThe only way around this problem is--unfortunately--to go through it. Like any other muscle that has atrophied, you must push through the pain and exercise the flesh for it to return to full function.", objectives = "Heal 5 Injured Deathguard with your Holy Light ability.", progress = "Mastery of the light will return, in time.", completion = "Pain is nothing new to those who have endured death, and as such the Forsaken are particularly hardy to it. Pain has a purifying property as well that you should embrace as a badge of honor and evidence that you are, in fact, still a servant of the light despite your new circumstances. \n\nBe well and walk in the light once more, {class}." }
WordHunterWoW_QuestEN[91208] = { title = "Coming to Terms", description = "Not all of our fellow Paladins who rise again are quick to acclimate to our new reality. Some struggle to reconcile that they are now, in a way, the very thing they spent their lives fighting against.\n\nThese individuals often simply need a kind gesture and a sympathetic ear. Unfortunately, many others are quick to turn violent. Find the frightened paladin who fled into the hills directly west of this chapel. Extend a hand in friendship. Lead them back into the light if you can.", objectives = "Find the Frightened Paladin in Deathknell.", completion = "Tragically, more than a few of our brothers and sisters succumb to a similar madness after being risen. As precious as every Forsaken soul is, sometimes the best we can do is grant those that cannot acclimate a clean end.\n\nI will say a prayer to the light for her. Thank you for doing what must be done, {name}." }
WordHunterWoW_QuestEN[91209] = { title = "Continue Your Training", description = "Lordaeron may not be what it used to be, but our home still needs protection from all manner of threats and it's time for you to go out and face the world. Your next stop should be the town of Brill in central Tirisfal Glades. Go and meet with Shari Stilwell there. She can see to your continued training. \n\nOne last bit of advice before you go--take extra care as a paladin traveling through Forsaken lands. There are many in the Dark Lady's service who distrust us and our proximity to the light.", objectives = "Follow the road east out of Deathknell to find the town of Brill. Report to Shari Stilwell to continue your training.", completion = "Welcome aboard, {class}. It's always encouraging to see more of our number roaming these lands. There are many here in Brill in need of assistance from adventurers such as yourself. Seek employment and grow stronger in the light. Return to me whenever you need training. \n\nWhen you've proven yourself to myself and the people of Brill, I will provide guidance for the next leg of your journey.\n\nGo with the light, {class}." }
WordHunterWoW_QuestEN[91282] = { title = "A Second Home", description = "It is encouraging to see my newly risen brothers and sisters thrive as you have. It is only through community and shared faith that we can truly realize our full potential however, and to that end we've begun to form a new paladin order right here in Tirisfal. \n\nIf you wish to learn more, you should visit our monastery on the edge of the Whispering Woods. It is called Bandarion Keep. It's on the bluffs just northwest of the Solliden Farmstead, and should be hard to miss.", objectives = "Find the fortress of Bandarion Keep and report to Breton Samuels there.", completion = "Another fresh recruit? Welcome to Tyr's Watch, brother." }
WordHunterWoW_QuestEN[91285] = { title = "Murlocs at the Gates", description = "Normally we'd show our newcomers a bit more hospitality, but we've got a bit of a murloc problem at the moment.\n\nA tribe of murlocs used to use the keep as their spawning grounds. They've been a problem since we moved in and kicked them out, but now it's starting to get out of hand. You look like you've seen some action. Do you think you could help us drive back some of these pests? You'll find them lurking in the bluffs along the road to the east, and in the camps around the lake to the west.", objectives = "Slay 8 Vile Fin Attackers and 8 Vile Fin Seers and report back to Breton Samuels when it is done.", completion = "We appreciate the assistance. I'm sure this won't stop the attacks entirely, but it'll hopefully slow them down a bit. It's hard enough rebuilding this place without a murloc trying to stab you in the back with a spear." }
WordHunterWoW_QuestEN[91294] = { title = "Touring the Grounds", description = "Now that the immediate threat of the murloc attacks is under control, I'd encourage you to show yourself around our stronghold. It isn't much yet, but it's home.\n\nWhen you are done exploring, seek out Danitha Morr, our leader. She can help you get settled in.\n\nI'm very glad to have met you, {name}. May the light be your guide.", objectives = "Speak to the residents of Bandarion Keep.", progress = "Welcome to Bandarion Keep, {class}. It's always good to see a new face.", completion = "Breton sent you up here, eh? Excellent.\n\nMy name is Danitha Morr, and I am the closest thing this keep has to a commander. If you come seeking fellowship amongst those that still remain loyal to the light, you've come to the right place.\n\nThere's a lot of work to do here before we can fully establish ourselves, and we'd be most appreciative if you would be willing to lend aid." }
WordHunterWoW_QuestEN[91316] = { title = "Making Repairs", description = "This far from the Undercity, logistics are challenging and we have a dire shortage of building materials needed to help restore this fortress. I'd like your help with that.\n\nThe ruined village of Shadowvale can be found in the Whispering Forest, just southwest of here. One of the buildings has an old root cellar used to store all sorts of things. There are likely to be usable materials down there. Scavenge what you can and return to us.", objectives = "Collect 12 pieces of Sturdy Lumber from Shadowvale in Tirisfal Glades.", progress = "They say location is everything. While this fortress may look imposing perched upon these bluffs, its turning out to be quite the challenge to stay supplied this far from proper civilization. An unfortunate oversight on our part.", completion = "I'm glad to see that your trip to Shadowvale bore fruit. I'll send Breton and a few of the other new recruits over later to clear the rest of the cellar out and retrieve anything left down in the dark." }
WordHunterWoW_QuestEN[91317] = { title = "The Tarnished", description = "Not all risen paladins have acclimated well to our new existence, as you may have seen yourself already. Some have carried forward their prejudices from life, and continue to visit violence upon their fellow Forsaken.\n\nAs it stands we are mistrusted by our people who remember well the persecution inflicted by the living in the name of the light, and these attacks do not help. A number of these tarnished have taken up residence at Shadowvale to the southwest. End them and bring me their leader's head.", objectives = "Slay 8 Tarnished Drudges, 6 Tarnished Zealots, and collect the head of Commander Rudolph Gelhardt in Tirisfal Glades.", progress = "The Tarnished threaten what little goodwill we have with the other Forsaken. As much as it pains me to cross blades with our former brothers and sisters, they must be stopped if our fledgling order is to survive.", completion = "Excellent work, {name}. Every time one of these Tarnished strike out and kill one of the Forsaken, it becomes that much easier for our detractors to stoke mistrust towards us paladins. Eliminating them will help further our cause and solidify our place here in Tirisfal.\n\nI suspect it may take a long time for us to be fully embraced by the Forsaken and the horde. It could take years... or maybe even decades, but the best we can do is keep trying to prove ourselves." }
WordHunterWoW_QuestEN[91488] = { title = "Home on the Range", description = "During our last skirmish with the blood elves, my tent was badly damaged. For three nights, I have been at the mercy of the elements.\n\nIt can be repaired with a few mosshoof hides, but a lack of sleep has left me unable to hunt them myself.\n\nThe easiest mosshooves to hunt are west and south of here, but the hide of any mooshoof will do.", objectives = "Bring 5 Mosshoof Hides to Kurll at Valormok in Azshara." }
WordHunterWoW_QuestEN[91497] = { title = "Seals of the Sin'dorei", description = "<The seal of the first crystal bears the mark of a sword. Its energy must be channeled by an expert warrior.\n\nThe seal of the middle crystal bears the mark of a glaive. Its energy must be channeled by one of both martial and magical prowess.\n\nThe seal of the last crystal bears the mark of a talon. Its energy must be channeled by one at home in the wilds.\n\nIt's likely that some of Rimtori's officers are carrying these seals to aid her in the spell. Taking them would no doubt be troublesome for her.>", objectives = "Bring the Seal of the Warden, Seal of the Warrior, and Seal of the Ranger to the Sin'dorei Tome of Summoning." }
WordHunterWoW_QuestEN[91500] = { title = "An Explosive Gambit", description = "<Seeing how the energies of the crystals are attuned to the seals, you reason that destroying a seal, thereby releasing its energy all at once, could cause its crystal to do the same.\n\nThe explosive results would certainly draw Rimtori's ire. It would also present the perfect opportunity to attack her while she's flustered.>", objectives = "Break the Seals of the Sin'dorei, then bring Magus Rimtori's head to Ag'tor Bloodfist in Valormok." }
WordHunterWoW_QuestEN[91531] = { title = "Revenge Exacted", description = "Return to Belgrom in Orgrimmar. He will want to see her head for himself!\n\nAh, this is indeed a good day. Thank you for your help, {name}.", objectives = "Bring the Head of Magus Rimtori to Belgrom Rockmaul in Orgrimmar." }
WordHunterWoW_QuestEN[91538] = { title = "Sin'dorei Tome of Summoning", description = "Rimtori's tome still sits atop its pedestal. Who knows what secrets its pages could hold? \n\nPerhaps it would be best not to leave such a powerful artifact out here in the wilds.", objectives = "Bring the Sin'dorei Tome of Summoning back to Jediga in Valormok." }
WordHunterWoW_QuestEN[91547] = { title = "Sin'dorei Tome of Summoning", description = "You were wise to take this, {name}. More than killing Rimtori, keeping this out of the blood elves' hands will ensure they are powerless to retaliate against us.\n\nAs for deciphering the tome itself, I have a contact in Orgrimmar who dabbles in such things--a warlock named Zevrost. He can be found in the Cleft of Shadow.", objectives = "Bring the Sin'dorei Tome of Summoning to Zevrost in Orgrimmar." }
WordHunterWoW_QuestEN[91548] = { title = "Vek'zol", description = "I do not speak Thalassian, but these diagrams are familiar to me.\n\nKnowing the blood elves' addiction to mana, I'd say they were trying to summon demons to drain them of their fel magic.\n\nSimply consuming such powerful energy is a waste. We could harness it for a much greater purpose.\n\n<Zevrost bookmarks a page in the tome>\n\nThere is an Altar of Storms in the Blasted Lands. Perform this ritual there to summon the demon Vek'zol. His heart will make a potent reagent. Think of the power we could have!", objectives = "Use the Sin'dorei Tome of Summoning to summon Vek'zol at the Altar of Storms in the Blasted Lands. Bring the Heart of Vek'zol to Zevrost in Orgrimmar." }
WordHunterWoW_QuestEN[91564] = { title = "Itching for a Fixing", description = "We've been stuck here for five years, and we've had to build everything from scratch! Do you know how much I've had to improvise just to do any engineering?\n\nHey, if you can help me out with some materials, I can make it worth your time! Build me a couple of Mithril Casings and a Mechanical Repair Kit so that I can fix up some stuff, and I'll show you a few things I've figured out.", objectives = "Bring 2 Mithril Casings and 1 Mechanical Repair Kit to Hnaz Blunderflame." }
WordHunterWoW_QuestEN[91568] = { title = "Long Walks on the Beach", description = "What the beaches here lack in looks, they make up for in value!\n\nMost of the ruins here have been picked clean, but there's some serious loot under that sand. Problem is, it's all scattered, and the naga make a long search a bit impractical. So, what's a girl to do?\n\nEnter the Treasure Trowel 3000! The all-in-one treasure detecting shovel! A personal invention of mine.\n\nTake this baby down to the eastern shore, and bring back whatever you find. Then, we can split the profits!", objectives = "Dig up 10 Highborne Treasure Fragments with the Treasure Trowel 3000 for Izvi Glidfizz in Valormok." }
WordHunterWoW_QuestEN[91569] = { title = "Blue Gold", description = "Listen kid, everyone out here's scramblin' for the same thing. Belgrom, the elves, the naga, they all wanna piece 'a that ancient highborne magic.\n\nMe? Couldn't care less, but I know a seller's market when I see one.\n\nI've seen blood elf arcanists carrying special wands. They're used to extract magical energy from artifacts the elves find. The arcanists stay at a camp east of the elves' base camp, along the cliffs. Get me one of those wands and I'll put you on to the score of a lifetime!", objectives = "Bring a Mana-Siphoning Wand to Izvi Gildfizz at Valormok." }
WordHunterWoW_QuestEN[91607] = { title = "Pay Dirt!", description = "<The large hunk of crystal is even heavier than it looks. While it appears to be quite the prize, its true nature is unknown to you. Someone with an eye for valuables could say what you've really found.>", objectives = "Find someone to appraise the Humongous Crystal." }
WordHunterWoW_QuestEN[91608] = { title = "Gettin' Buzzed", description = "There are few luxuries out here on the frontier. A barrel of good drink would surely boost the camp's morale.\n\nIn my younger days, I took a recipe for a delicious brew off the corpse of a dwarf I killed. All I need is some honey. Fortunately, the wasp nests to the west are overflowing with it.\n\nTake my pellet gun. This will allow you to knock the nests out of the trees. Be warned, however, it will do little against the wasps themselves.", objectives = "Gather 5 Wild Honey from Wasp Nests using Kurll's Pellet Gun." }
WordHunterWoW_QuestEN[91610] = { title = "Winter Frontier Fishery", description = "Meat is well and good, but a varied diet makes the body stronger.\n\nWinter squid are in season, and can be fished from the coasts here in Azshara. I never took to angling myself. I much prefer the safety of land. Although, were you to fish some up, or obtain them via some other means, I would greatly appreciate it.", objectives = "Fish up 10 Winter Squid for Kurll at Valormok." }
WordHunterWoW_QuestEN[91611] = { title = "Deadliest Catch", description = "If you wish for a true test of angling prowess, there are bigger fish than you can catch with a rod.\n\nMammoth Sharks lurk in the deepest waters of the northern and southern coasts. They swim far out, right before the sea floor drops away into the great ocean.\n\nThey are massive creatures. I would advise you to bring a hunting party. \n\nIf you do go after one, bring me a cut of the meat.", objectives = "Bring a Mammoth Shark Steak to Kurll at Valormok." }
WordHunterWoW_QuestEN[91685] = { title = "Ley of the Land", description = "When we first got here, I did some surveying for any untapped resources. Y'know, typical prospector stuff.\n\nI didn't see nothin' special 'til I searched Lake Mennar, to the south. There, I saw a huge rift floating above the water's surface. I couldn't get close, but I think it was an open leyline.\n\nIf I'm right, we can use this wand to siphon magic straight from the source! Bottle that up, sell it to the highest bidder, and bam! I'm rich!\n\nIf you go and siphon that rift for me, I'll cut you in.", objectives = "Use the Mana-Siphoning Wand on the Leyline Rift in Lake Mennar and bring the Tear of Mennar to Izvi Gildfizz." }
WordHunterWoW_QuestEN[91688] = { title = "To the Summit of Eternity", description = "You've managed to cut a swath through the undead that have kept us trapped here for so many years, and for that we can never repay you.\n\nI have one more favor to ask, on behalf of us all. We know that there are druids at the summit. They protect Nordrassil and the Well of Eternity.\n\nWhy did they never come help us to escape?\n\nFor five years we have been trapped here. At last we have a glimmer of hope... but why didn't the druids come for us?\n\nLet someone know that we're still alive!", objectives = "Travel to the Summit of Eternity and speak with the druids about the survivor village." }
WordHunterWoW_QuestEN[91696] = { title = "Open Season", description = "Deadwood set on my pup and his sire. He stood fast, fought to the death as our guard. We must go home, but the way is dark and full of jaws.\n\nStay near, guard us well. I will lead, you will fend, and we will see den safe.", objectives = "Escort the Barkskin Matriarch out of Deadwood Den and return to Barkskin Burrow." }
WordHunterWoW_QuestEN[91697] = { title = "Meet the Elders", description = "Thank you for helping gather bear berries. Small steps build trust! With the aroma of berry resin on you, the Elders should be more welcoming of you. \n\nGo and speak with Elder Mistpaw and Elder Pinespeaker.", objectives = "Find and speak with Elder Mistpaw and Elder Pinespeaker within Barkskin Burrow." }
WordHunterWoW_QuestEN[91698] = { title = "Barkskin Breakout", description = "<A matriarchal furbolg speaks to you from within the cage>\n\n\"Deadwood trap me and my cub in tough cage. Key hang on Deadwood Warden belt. You hunt them, take key, lift latch, set us free. Do this, and Barkskin know your heart true.\"", objectives = "Recover a Deadwood Key from a Deadwood Warden and return to the Barkskin Cage." }
WordHunterWoW_QuestEN[91723] = { title = "Delicate Instruments", description = "Blast it! Every time I try to calibrate these sensitive arcane instruments, they get thrown off again by a surge of energy.\nThe surges seem to be coming from the north, where those primitive Kobolds have been practicing their crude magic. Could you clear some of them out, so I can continue my work?", objectives = "Kill 8 Kobold Geomancers in Jasperlode Mine, then return to Hamish Bergwort in the Tower of Azora.", completion = "Well done, my friend. Let me try my calibrations again..." }
WordHunterWoW_QuestEN[91724] = { title = "Delicate Instruments", description = "Almost there, and... By the Nether! Something is still disrupting my instruments.\n\nThis is most frustrating, {name}. I have heard rumors that the local bandits have been practicing spells near Stone Cairn Lake. Maybe if you stop them, these disruptions will finally cease and I can get some work done?", objectives = "Kill 8 Defias Rogue Wizards at Stone Cairn Lake, then return to Hamish Bergwort in the Tower of Azora.", completion = "It seems like everything is working properly. Thank you, {name}." }
WordHunterWoW_QuestEN[91725] = { title = "Stolen Enchanting Supplies", description = "I was sent by Master Theocritus to pick up some enchanting supplies from the trading post, but on the way back I was ambushed by a pack of gnolls!\n\nI dropped the package and escaped, but if I return without it, I'll be cleaning up after the polymorph experiments for weeks as punishment! Do you think you could find the supplies for me?", objectives = "Collect 5 Stolen Enchanting Supplies from gnoll camps around Stone Cairn Lake, then return to Blixie Fitzwink near the Tower of Azora.", progress = "Did you find the supplies?", completion = "Oh, that's a relief! It looks like it's all here. Thank you!" }
WordHunterWoW_QuestEN[91732] = { title = "Good Steel", description = "Good steel is in short supply after the war, and our tools have suffered for it. The Jasperlode miners used finely-crafted picks, and I imagine some of them are still there in the depths of the mine. Could you retrieve some for me, and I'll see if I can repurpose the steel?", objectives = "Collect 4 Mining Tools from Jasperlode Mine, then return to Hagar Lowe in Eastvale Logging Camp.", progress = "Have you been to the mine yet?", completion = "Oh, very nice. Do you see that shine? Truly, they don't make them like they used to." }
WordHunterWoW_QuestEN[91733] = { title = "Downstream", description = "I was bringing back a supply shipment from the trading post, but my wagon tipped over and the supplies fell in the river! Before I could catch them, they had already washed downstream.\n\nBetween the murlocs and wolves down there, I don't stand a chance of retrieving the supplies on my own. You seem like the hardy sort. Do you think you could find them for me?", objectives = "Collect the Waterlogged Axe, Waterlogged Saw, and Waterlogged Toolbox that have washed downstream from Eastvale Logging Camp, then return to Ormin Pelford.", progress = "Did you find the supplies?", completion = "You look a bit damp, {name}. Sorry about that. But thank you for retrieving the supplies." }
WordHunterWoW_QuestEN[91734] = { title = "Remote Contact", description = "<The Forsaken sways unsteadily> \n\n'ey! <hic> Do me a favor ... would ya? \n\nGo to uh ... Azshara 'n ... tell <hic> Jediga ...\n\nExpectin' a ... 'mportant deliv'ry <hic>", objectives = "Speak to Jediga in Azshara." }
WordHunterWoW_QuestEN[91735] = { title = "Remote Contact", description = "Listen, {class}, you'd best not be hangin' round here for long. But since you are, perhaps you can do a little favor for me?\n\nI be expecting a certain something from a Jediga, in Azshara. She and some orcs be havin' a camp out there. Go and tell her Jes'rimon sent you, and I'll owe you one.", objectives = "Speak to Jediga in Azshara." }
WordHunterWoW_QuestEN[91736] = { title = "Applejack Still", description = "", objectives = "A strong scent of apples burns your nose as you inspect the device.", progress = "A strong scent of apples burns your nose as you inspect the device.", completion = "The machine dispenses a clear liquid into a bottle..." }
WordHunterWoW_QuestEN[91737] = { title = "Remote Contact", description = "My duties occasionally require reagents from the farther corners of Azeroth. However, I am always needed here in Thunder Bluff, and so I am in need of competent aides.\n\nTo that end, I am awaiting a delivery from an orc named Jediga, in Azshara. If you care to make yourself useful, find her camp, and inquire as to when I can expect it to arrive.", objectives = "Speak to Jediga in Azshara." }
WordHunterWoW_QuestEN[91738] = { title = "An Apple Treat", description = "", objectives = "The sergeant's eyes light up as he notices your bottle of Thunder Applejack...", progress = "The sergeant's eyes light up as he notices your bottle of Thunder Applejack...", completion = "Do my eyes deceive me? I haven't seen a drop of Thunder Applejack in months!\nThis should put a smile on the troops' faces. You have my thanks, {class}!" }
WordHunterWoW_QuestEN[91740] = { title = "Croaky's Head", description = "This murloc has no doubt been terrorizing the local roads for some time. You suspect the nearby watch guards will want to know of its demise.", objectives = "Deliver Croaky's Head to Merell Ross at Ridgepoint Tower.", progress = "Yes?", completion = "We lost two members of the watch last week to the murlocs, {class}. Hopefully with their leader slain, we can start pushing them out of Elwynn." }
WordHunterWoW_QuestEN[91741] = { title = "Nibbled-On Book", description = "<One of the kobolds dropped this book. It looks like the kobold might have tried to eat it.\n\nBrother Paxton inside the abbey has a small library he maintains. The book must have come from there.>", objectives = "Return the book to Brother Paxton.", progress = "What's that you got there? It looks like one of my books.", completion = "Hey! How did you end up with that? It's supposed to be on the shelf! Oh dear, the kobolds have been stealing my books again. They must want to eat them!\n\nThanks for bringing back the book, but what will I do about the rest of my missing collection?" }
WordHunterWoW_QuestEN[91743] = { title = "Rascally Rodents", description = "Those awful kobolds are eating my books! You have to get them back before they devour my whole library.", objectives = "Retrieve 8 Stolen Books from kobolds in Northshire Valley and return them to Brother Paxton.", progress = "Have you rescued my books yet, {name}?!", completion = "Thank you so much! Here! Take one of these how-to books. I don't need them.\n\nBut there are still so many books missing. The kobolds don't seem to be eating them. So, why do they want them?" }
WordHunterWoW_QuestEN[91745] = { title = "Mining Consultant", description = "Go talk to the new mining apprentice, Kelsey Fargo. She works right outside the mine and has probably seen what the kobolds are up to. Maybe she can teach you a thing or two about mining while you're at it.", objectives = "Talk to Kelsey Fargo outside the Echo Ridge Mine in Northshire Valley.", completion = "Kobolds with books? Yah, I've seen kobolds running back and forth with books, yelling at each other. They must be stealing them from the library inside the abbey." }
WordHunterWoW_QuestEN[91746] = { title = "Elmpaw's Head", description = "The trophy serves as an impressive reminder of your victory over Elmpaw. A local hunter or skinner might be interested to hear the story.", objectives = "Deliver Elmpaw's Head to Helene Peltskinner near Goldshire.", progress = "Yes?", completion = "So, you took down Elmpaw? Very impressive, {name}!\n\nLet me give you something in return for your trophy - I know a few collectors who will pay quite well to have this on their mantle once I've prepared it." }
WordHunterWoW_QuestEN[91751] = { title = "Rough Wolf Pelts", description = "Are you looking for an opportunity to practice skinning? My husband usually helps with hunting wolves, but he's busy up by the abbey. I could use a hand collecting more pelts to finish the orders I'm working on.", objectives = "Skin wolves around Elwynn Forest to obtain 7 Rough Wolf Pelts, then deliver them to Helene Peltskinner near Goldshire.", progress = "Any luck with those wolf pelts?", completion = "Excellent work collecting these pelts, {class}. You have a real talent for hunting." }
WordHunterWoW_QuestEN[91752] = { title = "The Big Picture", description = "Every once in a while, a kobold comes through yelling \"Picture for Narf!\" I don't know who Narf is. Maybe one of the head kobolds at the back of the mine? I bet he has a whole sack of books by now.\n\nGo get those books and bring them to our local law enforcement, Marshal McBride. You should find a friend to help. Those kobolds inside the mine are a lot meaner.", objectives = "Retrieve a Sack of \"Picture\" Books from Shinyfinder Narf. Bring the sack to Marshal McBride just inside Northshire's Abbey.", progress = "Have you retrieved those stolen books yet?", completion = "Thank you for returning these stolen books, {name}. I'll get them back to Brother Paxton at once.\n\nYou're becoming quite the hero around here. Great job!" }
WordHunterWoW_QuestEN[91753] = { title = "An Enchanting Lesson", description = "Academic rigor is of course essential to the enchanter's craft, but a practical foundation can pay dividends. Consider, as an example, the lowly Kobold. Lacking formal education, they nevertheless demonstrate a sort of innate aptitude for simple cantrips and enchantments.\n\nObtain some of their wax effigies and deconstruct the enchantments bound within them. You may find it elucidating.", objectives = "Kitta Firewind in the Tower of Azora wants you to collect 3 Luminous Residue.\n\nLuminous Residue can be obtained by disenchanting Crude Wax Effigies dropped by Kobold Geomancers.", progress = "What have your studies revealed?", completion = "Theory and practice are two sides of a coin, {name}. Remember this." }
WordHunterWoW_QuestEN[91754] = { title = "Rub Some Dirt In It", description = "I haven't seen |5{race} like you in years!\n\nOh, I don't know what to do! My friend Fraxinus is sick, and I can't leave him alone!\n\nCould you please fetch me some Untainted Soil from the uncorrupted land southeast of here? I can make some poultices that may help him to feel better.", objectives = "Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal." }
WordHunterWoW_QuestEN[91755] = { title = "Leaves to Ligatures", description = "Have you seen those nasty tainted shrubberies wandering around this valley?\n\nThose plants are mean, but some of them are not entirely toxic. Their leaves can have medicinal purposes.\n\nWould you be so kind as to fetch me some Verdant Leaves? You'll have to do a little pruning, of course.", objectives = "Collect 12 Verdant Leaves from Tainted Shrubbery in the foothills of Mount Hyjal." }
WordHunterWoW_QuestEN[91758] = { title = "Follow That Kobold!", description = "You're not done with those kobolds yet. We just got word from Kelsey that a kobold left the mine carrying a large sack of books. I need you to track down this kobold so we can retrieve the books for Brother Paxton.\n\nGo talk to Tordrin Sternblade. He's the new Hunter trainer that just arrived from Ironforge. You can find him behind the abbey, near the stable. He can help you track this kobold thief.", objectives = "Speak to Tordrin Sternblade near the stable behind Northshire's Abbey.", completion = "I can help ye' track down this varmint. Let me whip somethin' up for ye'." }
WordHunterWoW_QuestEN[91770] = { title = "Bark Bite", description = "With the ingredients you brought, I can make some simple medicine. This poultice should aid Fraxinus. He is old, you know, and he was badly burned during the wars. His bark hurts and his limbs ache. He is my best friend and I just want him to feel better!\n\nTake this poultice and apply it liberally to all of the places where his bark is split and his sap is weeping.", objectives = "Apply the poultice to Fraxinus." }
WordHunterWoW_QuestEN[91772] = { title = "Shhh! We're Hunting Kobolds", description = "Alright. Take this kobold tracking kit. It'll let ye' track the kobold that Marshal McBride is concerned with.\n\nFollow the tracks and bring what ye' find to Marshal Dughan in Goldshire.\n\nI have a feelin' these varmints are up to somethin' outside Northshire. So ye'll be needin' Dughan's help.", objectives = "Follow the kobold tracks and report to Marshal Dughan in Goldshire with your findings and the Kobold Tracking Kit.", progress = "Have you figured out where the Kobolds are heading?", completion = "What's this, {name}? Tracking kobolds?\n\nWell, of course they're headed toward the Fargodeep mine! That place is infested with kobolds.\n\nGood work, I guess. I'm going to need someone to take care of that problem." }
WordHunterWoW_QuestEN[91775] = { title = "Book Return", description = "While you're investigating the Fargodeep Mine, see if you can find any of Brother Paxton's books to return. In particular, Paxton is very concerned about a book titled, \"Fun with Elementals\". He thinks even a kobold could use it to summon an elemental servant. Be warned, the depths of the mine are fairly dangerous. You should bring friends.\n\nTake this book bag to protect the books when you find them!", objectives = "Find 6 Lost Books and \"Fun with Elementals\" and return them to Marshal Dughan.", progress = "Have you found all the books yet?", completion = "I applaud your diligence, {name}. Brother Paxton sent a list of books, and you've found most of the missing ones. The rest must have been taken to the Jasperlode Mine.\n\nYou can keep that book bag!" }
WordHunterWoW_QuestEN[91777] = { title = "Rare Books", description = "There are just two books left missing on Brother Paxton's list: \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\".\n\nThe kobolds must have taken them to the Jasperlode Mine. Please track down those two books and bring them back to Brother Paxton.\n\nBut I'm afraid it will be quite dangerous. If the \"apprentice\" kobold was summoning an elemental, who knows what the master can do. I'd bring some friends if I were you.", objectives = "Recover \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\" and return them to Brother Paxton inside Northshire's Abbey.", progress = "Have you found all my missing books yet?", completion = "Oh, {name}! Thank you so much for saving my library. You've done me an amazing service. Please take one of these fine weapons. They were intended for the militia, but you can make better use of them." }
WordHunterWoW_QuestEN[91794] = { title = "Flags of Our Forebears", description = "We been stuck up here for years, always fighting against de Scourge, but we never lose hope. We fight to survive. We fight for da Horde. Da Alliance shares dis fight, but we never forget dat we still got history. Still got blood.\n\nFar to da east, at Dae'gun, dere are Horde flags from da war. Da demons carry scraps and remains as trophies from da battle, especially da tough ones. Bring me a flag and some heraldry so I can put it up and show da Alliance dat da Horde is still strong!", objectives = "Collect 1 Horde Flag and 3 Scraps of Horde Heraldry for Kal'tinzan at Elderwild." }
WordHunterWoW_QuestEN[91858] = { title = "Diplomatic Incident", description = "A most unfortunate turn of events in Silverpine has presented a unique opportunity for us to prove our worth in the eyes of the horde.\n\nA pair of dignitaries from the Earthen Ring went missing in Silverpine Forest en route to Tarren Mill. We don't know much else but rumors say that this is becoming quite the diplomatic incident. If we can recover these missing persons, it could help gain us the legitimacy we so dearly need.\n\nWe have a man at The Sepulcher, Trevan Rol. Travel there and speak with him.", objectives = "Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers.", completion = "Danitha sent you? Well in that case I already know why you are here. You just walked into a damned fine mess, {class}." }
WordHunterWoW_QuestEN[91859] = { title = "A Curious Pair", description = "Cutting straight to it, these \"dignitaries\" are no ordinary diplomats. One was a Tauren. Ordinary enough for the Earthen Ring, but the other--and you'll scarcely believe this--was an elf. A *high* elf. They were cloaked, but I've seen quel'dorei before and I'd bet my good pinky finger that's what I saw.\n\nWhy was an elf accompanying a Tauren through horde territory? Well, your guess is as good as mine. That's as much as I know, so I'd suggest speaking with Deathguard Baldren near the entrance to town.", objectives = "Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher.", completion = "I might not care for you paladins, but I will say that your timing is impeccable. It's better to be lucky than good, I suppose?" }
WordHunterWoW_QuestEN[91860] = { title = "A Grim Fate", description = "Out on patrol last night I spotted a group of gnolls dumping a very large body onto a pyre on the shores of Fenris Isle. I didn't see an elf or any smaller corpses, but I'd say this doesn't bode well for them.\n\nIf you are brave or stupid you are welcome to charge into Fenris Isle to learn more, but if you ask me, it's a lot of work to find some snooty elf that's probably long dead.\n\nI know you paladins love swearing oaths and taking on lost causes, but this one isn't worth it. Trust me.", objectives = "Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party.", completion = "<The corpse before you was certainly Tauren and you can tell that it was gnawed on heavily before it was tossed onto the pyre. You see no signs of the elf woman that was described to you though. Perhaps she is still alive somewhere deeper in the fortress nearby?\n\nThis will be dangerous, but there's only one way to find out for sure.>" }
WordHunterWoW_QuestEN[91861] = { title = "Into Fenris Keep", description = "<The fact that you found only one body is a hopeful sign. Perhaps the High Elf that Trevan and Hadrec described is still alive somewhere deeper inside the nearby fortress?>", objectives = "Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party.", completion = "You are one of the Forsaken, yes? Can you help free me? \n\nTime is short for me, I am afraid. Please hurry!" }
WordHunterWoW_QuestEN[91862] = { title = "Lumina Windsinger", description = "Quel'dorei? No, I am no \"quel'dorei\". I am Lumina Windsinger and I am shen'dorei. One of the Windshaper Skyborne.\n\nI came to these lands as a guest of the Earthen Ring. My companion Banon and I were passing through Silverpine to reach the Arathi Highlands so that we could study the elemental convergences there. Clearly, we didn't make it.\n\nWe have no time for this now though. Kill the gnolls nearby. Retrieve the key to this cage and free me. I will tell you the rest once we are safely away.", objectives = "Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger.", progress = "Gnolls are the second worst creatures I've encountered yet on Azeroth.", completion = "Thank you, {class}. Unfortunately we aren't out of danger yet." }
WordHunterWoW_QuestEN[91877] = { title = "Demon Hunter's Hunter", description = "Not many demon hunters remain on Azeroth now, but a few of us continue to hunt the most dangerous or hidden threats.\n\nA colleague of mine, Maerion Thaelemaches, headed to Hyjal to investigate rumors of demons there. While there are many demons in the dangerous Darkwhisper Gorge, there is suspicion that the demons that assaulted the mountain during the last war might not be completely defeated.\n\nThis bears investigation.", objectives = "Find Maerion Thaelemaches somewhere on Mount Hyjal." }
WordHunterWoW_QuestEN[91881] = { title = "The Western Post", description = "With the warlocks under control, I'd say this area's well in wing.\n\n<The crow nods sagely, looking pleased.>\n\nThough our work here is done, there are other areas that could use your help and as an underwing of mine I would like you to go see what all the fuss is about.\n\nFollow the path northwest up the road to the old tern outpost. An old friend awaits!", objectives = "Meet Sefira Everbright at the outpost." }
WordHunterWoW_QuestEN[91882] = { title = "The Grand Alliance", description = "Years ago, the Horde and the Alliance put aside their differences to fight a greater threat--the Legion. On Mount Hyjal, the Grand Alliance forces battled Archimonde and his minions to a halt.\n\nThe retreat from the mountain was perilous, however, and some brave fighters were left behind.\n\nNow that the way up the great mountain is again open, perhaps some of these heroes remain alive in the wilds? Go to Mount Hyjal and brave its dangers. Find what became of our forces there.", objectives = "Search Mount Hyjal for remnants of the Grand Alliance." }
WordHunterWoW_QuestEN[91883] = { title = "Spear of the Skylord", description = "While fighting off the Wormwing harpies I was brutally ambushed by a harpy named Zarrat who patrols this area. She snatched my spear and carried it off before I could recover. To what end she desired to possess it, I cannot say.\n\nThat spear has been in my family for generations and is of great importance to me. If you spot Zarrat among the harpies, slay her and return my spear. She is stealthy, and will not be easily found, but I would be grateful to have my spear returned.", objectives = "Slay Zarrat Wormwing and return Omnuron's Spear." }
WordHunterWoW_QuestEN[91899] = { title = "A Sealed Crate", description = "", objectives = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", progress = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", completion = "Thank you for your hard work, {name}. There has been an uprising in bandits and thieves intercepting trade routes as of late. If you find other crates lying around, please bring them here and we'll handle the rest.\n\nHere is your payment." }
WordHunterWoW_QuestEN[91900] = { title = "A Sealed Crate", description = "", objectives = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", progress = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", completion = "Thank you for your hard work, {name}. There has been an uprising in bandits and thieves intercepting trade routes as of late. If you find other crates lying around, please bring them here and we'll handle the rest.\n\nHere is your payment." }
